const { PrismaClient } = require('@prisma/client');
const fs = require('fs');
const path = require('path');

const prisma = new PrismaClient();

async function main() {
  console.log('Iniciando backup da tabela Exercise...');
  const exercises = await prisma.exercise.findMany();

  // Cria um nome leg├¡vel ex: backup_exercicios_originais_2026-07-17_13-55.json
  const date = new Date();
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const hours = String(date.getHours()).padStart(2, '0');
  const minutes = String(date.getMinutes()).padStart(2, '0');

  const backupFilename = `backup_exercicios_originais_${year}-${month}-${day}_${hours}-${minutes}.json`;

  // Salva na raiz do projeto
  const backupPath = path.join(__dirname, '..', backupFilename);

  fs.writeFileSync(backupPath, JSON.stringify(exercises, null, 2), 'utf-8');
  console.log(`Backup salvo com sucesso em: ${backupPath}`);
  console.log(`Total de exerc├¡cios salvos: ${exercises.length}`);
}

main()
  .catch((e) => {
    console.error('Erro ao fazer backup:', e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

const fs = require('fs');
const path = require('path');

const rawDatasetPath = path.join(__dirname, '..', 'prisma', 'seeds', 'exercises_raw.json');
const rawEnglishList = JSON.parse(fs.readFileSync(rawDatasetPath, 'utf8'));

const targets = new Set();
const categories = new Set();
const equipments = new Set();

rawEnglishList.forEach(ex => {
  if (ex.target) targets.add(ex.target);
  if (ex.category) categories.add(ex.category);
  if (ex.equipment) equipments.add(ex.equipment);
});

console.log("Targets:", Array.from(targets));
console.log("Categories:", Array.from(categories));
console.log("Equipments:", Array.from(equipments));

const { chromium } = require("playwright");
const fs = require("fs");
const path = require("path");

async function main() {
  const screenshotsDir = path.join(__dirname, "..", "screenshots");
  if (!fs.existsSync(screenshotsDir)) {
    fs.mkdirSync(screenshotsDir, { recursive: true });
  }

  console.log("Iniciando navegador Playwright...");
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 1440, height: 900 },
    deviceScaleFactor: 2,
  });

  const page = await context.newPage();

  // 1. Landing Page
  console.log("1. Capturando Landing Page...");
  await page.goto("http://localhost:3000", { waitUntil: "networkidle" });
  await page.waitForTimeout(1500);
  await page.screenshot({ path: path.join(screenshotsDir, "01_landing_page.png"), fullPage: false });

  // 2. Login Page
  console.log("2. Capturando Tela de Login...");
  await page.goto("http://localhost:3000/login", { waitUntil: "networkidle" });
  await page.waitForTimeout(1500);
  await page.screenshot({ path: path.join(screenshotsDir, "02_login_page.png"), fullPage: false });

  // 3. Dashboard do Treinador
  console.log("3. Efetuando login como Treinador e capturando Dashboard...");
  await page.goto("http://localhost:3000/login");
  await page.fill('input[type="email"]', "trainer@test.com");
  await page.fill('input[type="password"]', "123456");
  await page.click('button[type="submit"]');
  await page.waitForURL("**/trainer/dashboard", { timeout: 15000 }).catch(() => {});
  await page.waitForTimeout(2500);
  await page.screenshot({ path: path.join(screenshotsDir, "03_trainer_dashboard.png"), fullPage: false });

  // 4. Dashboard do Aluno
  console.log("4. Efetuando login como Aluno e capturando Dashboard/Gamifica├º├úo...");
  await context.clearCookies();
  await page.goto("http://localhost:3000/login");
  await page.fill('input[type="email"]', "student@test.com");
  await page.fill('input[type="password"]', "123456");
  await page.click('button[type="submit"]');
  await page.waitForURL("**/student/dashboard", { timeout: 15000 }).catch(() => {});
  await page.waitForTimeout(2500);
  await page.screenshot({ path: path.join(screenshotsDir, "04_student_dashboard.png"), fullPage: false });

  console.log("Todas as 4 capturas de tela foram conclu├¡das com sucesso!");
  await browser.close();
}

main().catch((err) => {
  console.error("Erro durante a captura de telas:", err);
