const { PrismaClient } = require('@prisma/client');
const fs = require('fs');
const path = require('path');

const prisma = new PrismaClient();

async function main() {
  console.log("=== TECHFITNESS DB CLEANUP & SEEDING TRANSLATED EXERCISES ===");

  // 1. Carregar arquivos de suporte
  const backupPath = path.join(__dirname, '..', 'backup_exercicios_originais_2026-07-17_13-54.json');
  const mappedGifsPath = path.join(__dirname, '..', 'prisma', 'seeds', 'mapped_core_gifs.json');
  const rawPath = path.join(__dirname, '..', 'prisma', 'seeds', 'exercises_raw.json');
  const ptbrPath = path.join(__dirname, '..', 'prisma', 'seeds', 'exercises_ptbr.json');

  if (!fs.existsSync(backupPath)) {
    console.error("ÔØî Arquivo de backup n├úo encontrado em " + backupPath);
    return;
  }
  if (!fs.existsSync(mappedGifsPath)) {
    console.error("ÔØî Arquivo mapped_core_gifs.json n├úo encontrado em " + mappedGifsPath);
    return;
  }
  if (!fs.existsSync(rawPath)) {
    console.error("ÔØî Arquivo exercises_raw.json n├úo encontrado em " + rawPath);
    return;
  }
  if (!fs.existsSync(ptbrPath)) {
    console.error("ÔØî Arquivo exercises_ptbr.json n├úo encontrado em " + ptbrPath);
    return;
  }

  const backupExercises = JSON.parse(fs.readFileSync(backupPath, 'utf8'));
  const mappedGifs = JSON.parse(fs.readFileSync(mappedGifsPath, 'utf8'));
  const rawExercises = JSON.parse(fs.readFileSync(rawPath, 'utf8'));
  const ptbrExercises = JSON.parse(fs.readFileSync(ptbrPath, 'utf8'));

  const coreIds = new Set(backupExercises.map(ex => ex.id));
  console.log(`Carregados ${backupExercises.length} exerc├¡cios core da biblioteca original.`);

  // Identificar o exerc├¡cio em ingl├¬s referenciado em logs/treinos
  const referencedEnglishId = "cmrp7kl6b0090tjfwm0neczu3"; // "3/4 sit-up"

  // 2. Limpar os exerc├¡cios em ingl├¬s que n├úo est├úo sendo utilizados
  console.log("Limpando exerc├¡cios em ingl├¬s n├úo referenciados...");
  const dbExercises = await prisma.exercise.findMany({
    select: { id: true, name: true }
  });

  const idsToDelete = [];
  dbExercises.forEach(ex => {
    if (!coreIds.has(ex.id) && ex.id !== referencedEnglishId) {
      idsToDelete.push(ex.id);
    }
  });

  console.log(`Deletando ${idsToDelete.length} exerc├¡cios n├úo utilizados do banco de dados...`);
  if (idsToDelete.length > 0) {
    const deleteResult = await prisma.exercise.deleteMany({
      where: {
        id: { in: idsToDelete }
      }
    });
    console.log(`Deletados ${deleteResult.count} exerc├¡cios com sucesso.`);
  }

  // 3. Renomear o exerc├¡cio de ID "cmrp7kl6b0090tjfwm0neczu3" de "3/4 sit-up" para "Abdominal 3/4"
  console.log("Renomeando o exerc├¡cio em ingl├¬s referenciado...");
  const refExercise = await prisma.exercise.findUnique({
    where: { id: referencedEnglishId }
  });

  if (refExercise) {
    await prisma.exercise.update({
      where: { id: referencedEnglishId },
      data: {
        name: "Abdominal 3/4",
        muscleGroup: "Core",
        equipment: "Peso Corporal",
        gifUrl: "videos/0001-2gPfomN.gif" // GIF do 3/4 sit-up
      }
    });
    console.log(`Exerc├¡cio ${referencedEnglishId} renomeado com sucesso para 'Abdominal 3/4'.`);
  } else {
    console.log("ÔÜá´©Å Exerc├¡cio referenciado n├úo encontrado no banco.");
  }

  // 4. Restaurar/Atualizar a biblioteca original (340 exerc├¡cios)
  // Isso garante que todos os IDs originais e nomes originais continuem id├¬nticos
  console.log("Garantindo integridade dos 340 exerc├¡cios core originais...");

  // Criar um mapeamento r├ípido dos GIFs das correspond├¬ncias
  const gifMap = new Map(); // id do exercicio core -> gifUrl
  mappedGifs.forEach(mg => {
    if (mg.gifUrl) {
      gifMap.set(mg.id, mg.gifUrl);
    }
  });

  for (const origEx of backupExercises) {
    const existing = await prisma.exercise.findUnique({
      where: { id: origEx.id }
    });

    const finalGifUrl = gifMap.get(origEx.id) || origEx.gifUrl || null;

    if (existing) {
      // Atualiza mantendo os dados originais e injetando o GIF
      await prisma.exercise.update({
        where: { id: origEx.id },
        data: {
          name: origEx.name,
          muscleGroup: origEx.muscleGroup,
          equipment: origEx.equipment,
          description: origEx.description,
          videoUrl: origEx.videoUrl,
          gifUrl: finalGifUrl
        }
      });
    } else {
      // Se foi deletado acidentalmente, reinsere com o ID correto
      await prisma.exercise.create({
        data: {
          id: origEx.id,
          name: origEx.name,
          muscleGroup: origEx.muscleGroup,
          equipment: origEx.equipment,
          description: origEx.description,
          videoUrl: origEx.videoUrl,
          gifUrl: finalGifUrl
        }
      });
    }
  }
  console.log("Biblioteca core original de 340 exerc├¡cios garantida e atualizada.");

  // 5. Inserir exerc├¡cios traduzidos n├úo duplicados
  console.log("Iniciando importa├º├úo dos exerc├¡cios traduzidos adicionais...");

  // Criar um Set dos nomes em ingl├¬s que foram mapeados/associados ├á biblioteca original
  const matchedEnglishNames = new Set(
    mappedGifs
      .map(mg => mg.matchedEnglishName ? mg.matchedEnglishName.toLowerCase() : null)
      .filter(Boolean)
  );

  // Tamb├®m n├úo podemos importar "3/4 sit-up" de novo porque j├í o renomeamos
  matchedEnglishNames.add("3/4 sit-up");

  let novosInseridos = 0;
  let duplicadosPulados = 0;

  for (let i = 0; i < rawExercises.length; i++) {
    const rawEx = rawExercises[i];
    const ptbrEx = ptbrExercises[i];

    const rawNameLower = rawEx.name.toLowerCase();

    // Se o exerc├¡cio foi mapeado para a biblioteca original, pulamos para evitar duplicata
    if (matchedEnglishNames.has(rawNameLower)) {
      duplicadosPulados++;
      continue;
    }

    // Tenta encontrar por nome em portugu├¬s para evitar duplicar
    const normalizedNewName = ptbrEx.name.trim();
    const existingByName = await prisma.exercise.findUnique({
      where: { name: normalizedNewName }
    });

    if (!existingByName) {
      await prisma.exercise.create({
        data: {
          name: normalizedNewName,
          muscleGroup: ptbrEx.muscleGroup || 'Geral',
          equipment: ptbrEx.equipment || 'Peso Corporal',
          description: ptbrEx.description || null,
          gifUrl: ptbrEx.gifUrl || null,
          videoUrl: null
        }
      });
      novosInseridos++;
    }
  }

  const finalTotal = await prisma.exercise.count();
  console.log("\n=== CONCLU├ìDO ===");
  console.log(`- Exerc├¡cios duplicados pulados (j├í representados na biblioteca original): ${duplicadosPulados}`);
  console.log(`- Novos exerc├¡cios traduzidos inseridos com sucesso: ${novosInseridos}`);
  console.log(`- Total de exerc├¡cios final no banco: ${finalTotal}`);
}

main()
  .catch(console.error)
  .finally(async () => {
    await prisma.$disconnect();
  });

