const rawDatasetPath = path.join(__dirname, '..', 'prisma', 'seeds', 'exercises_raw.json');
const outputPath = path.join(__dirname, '..', 'prisma', 'seeds', 'mapped_core_gifs.json');

async function matchBatch(portugueseBatch, rawEnglishList) {
  const prompt = `
Voc├¬ ├® um especialista em educa├º├úo f├¡sica e muscula├º├úo.
Mapeie cada exerc├¡cio em portugu├¬s para o seu correspondente em ingl├¬s no dataset fornecido.
O objetivo ├® encontrar o exerc├¡cio em ingl├¬s que seja o mesmo movimento f├¡sico para que possamos usar o GIF dele.
Se n├úo houver correspondente exato, encontre o mais pr├│ximo (ex: varia├º├Áes com barra, halteres, cabo ou m├íquina que fa├ºam o mesmo movimento).
Se n├úo houver nenhum exerc├¡cio semelhante, retorne null no campo "matchedEnglishName".

Retorne APENAS um array JSON contendo objetos no seguinte formato:
[
  { "id": "id_do_exercicio_em_portugues", "portugueseName": "nome_em_portugues", "matchedEnglishName": "nome_do_exercicio_em_ingles_do_dataset" }
]
Retorne APENAS o JSON bruto, sem formata├º├úo markdown (como \`\`\`json) ou qualquer outro texto explicativo.

Exerc├¡cios em Portugu├¬s:
${JSON.stringify(portugueseBatch.map(ex => ({ id: ex.id, name: ex.name, muscleGroup: ex.muscleGroup, equipment: ex.equipment })), null, 2)}

Exerc├¡cios em Ingl├¬s Dispon├¡veis (Dataset):
${JSON.stringify(rawEnglishList.map(ex => ({ name: ex.name, target: ex.target, equipment: ex.equipment })), null, 2)}
`;

  try {
    const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${API_KEY}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: {
          temperature: 0,
          responseMimeType: "application/json"
        }
      })
    });

    const data = await response.json();
    if (data.error) {
      console.error("Erro na API Gemini:", data.error.message);
      return [];
    }

    let textResponse = data.candidates[0].content.parts[0].text;
    textResponse = textResponse.replace(/```json/g, '').replace(/```/g, '').trim();

    return JSON.parse(textResponse);
  } catch (error) {
    console.error('Erro ao mapear lote:', error);
    return [];
  }
}

async function main() {
  console.log("Lendo exerc├¡cios do banco de dados com gifUrl nulo...");
  const dbExercises = await prisma.exercise.findMany({
    where: { gifUrl: null }
  });
  console.log(`Total de exerc├¡cios sem GIF no DB: ${dbExercises.length}`);

  if (dbExercises.length === 0) {
    console.log("Todos os exerc├¡cios j├í possuem GIF!");
    return;
  }

  console.log("Lendo dataset raw em ingl├¬s...");
  const rawEnglishList = JSON.parse(fs.readFileSync(rawDatasetPath, 'utf8'));
  console.log(`Total de exerc├¡cios em ingl├¬s no dataset: ${rawEnglishList.length}`);

  const BATCH_SIZE = 180;
  let allMapped = [];

  // Se j├í existir um progresso parcial, carrega para n├úo perder
  if (fs.existsSync(outputPath)) {
    try {
      allMapped = JSON.parse(fs.readFileSync(outputPath, 'utf8'));
      console.log(`Carregado progresso anterior: ${allMapped.length} exerc├¡cios mapeados.`);
    } catch (e) {
      console.log("Criando novo mapeamento.");
    }
  }

  const mappedIds = new Set(allMapped.map(m => m.id));
  const remainingExercises = dbExercises.filter(ex => !mappedIds.has(ex.id));
  console.log(`Exerc├¡cios restantes para processar: ${remainingExercises.length}`);

  for (let i = 0; i < remainingExercises.length; i += BATCH_SIZE) {
    const batch = remainingExercises.slice(i, i + BATCH_SIZE);
    console.log(`Processando lote ${Math.floor(i / BATCH_SIZE) + 1} de ${Math.ceil(remainingExercises.length / BATCH_SIZE)}... (${batch.length} exerc├¡cios)`);

    let retries = 0;
    let success = false;

    while (!success && retries < 3) {
      console.log(`Tentativa ${retries + 1}/3...`);
      const result = await matchBatch(batch, rawEnglishList);

      if (result && result.length > 0) {
        allMapped = allMapped.concat(result);
        fs.writeFileSync(outputPath, JSON.stringify(allMapped, null, 2), 'utf8');
        console.log(`Lote conclu├¡do e salvo com sucesso. Total mapeado at├® agora: ${allMapped.length}`);
        success = true;
      } else {
        retries++;
        if (retries < 3) {
          console.log("Falha ou limite atingido. Aguardando 45 segundos antes de tentar novamente...");
          await new Promise(resolve => setTimeout(resolve, 45000));
        }
      }
    }

    if (!success) {
      console.log("ÔØî Parando o processamento devido a falhas consecutivas.");
      break;
    }

    // Delay de 15 segundos entre requisi├º├Áes para evitar rate limit
    if (i + BATCH_SIZE < remainingExercises.length) {
      console.log("Aguardando 15s para o pr├│ximo lote...");
      await new Promise(resolve => setTimeout(resolve, 15000));
    }
  }

  console.log(`\nÔ£à Mapeamento conclu├¡do! ${allMapped.length} de ${dbExercises.length} exerc├¡cios mapeados.`);
  console.log(`Resultado salvo em: ${outputPath}`);
}

main().catch(console.error).finally(() => prisma.$disconnect());

