function translateName(name) {
  let lower = name.toLowerCase().trim();

  // Casos especiais diretos
  if (lower === "3/4 sit-up") return "Abdominal 3/4";
  if (lower === "air bike") return "Bicicleta ergom├®trica ar";
  if (lower === "burpee") return "Burpee";

  // Ordena as chaves do maior para o menor para evitar substitui├º├Áes parciais incorretas
  const sortedKeys = Object.keys(dictionary).sort((a, b) => b.length - a.length);

  let equipment = "";
  let position = "";
  let exercise = "";
  let details = [];

  // Extrair componentes conhecidos do nome em ingl├¬s
  for (const key of sortedKeys) {
    if (lower.includes(key)) {
      const val = dictionary[key];
      // Classifica o termo traduzido
      if (["com barra", "com halter", "na polia", "na m├íquina", "com el├ístico", "com kettlebell", "com bola medicinal", "na bola su├¡├ºa", "no bosu", "no smith", "na m├íquina articulada", "no leg press", "com roda abdominal", "com rolo"].includes(val)) {
        if (!equipment) {
          equipment = val;
          lower = lower.replace(key, "");
        }
      } else if (["sentado", "em p├®", "deitado", "declinado", "inclinado", "reto", "pronado", "supinado", "ajoelhado", "semiajoelhado"].includes(val)) {
        if (!position) {
          position = val;
          lower = lower.replace(key, "");
        }
      } else if (["supino", "flex├úo de bra├ºo", "puxada na barra", "puxada supinada na barra", "puxada", "remada", "agachamento", "levantamento terra", "stiff", "rdl", "leg press", "extens├úo de pernas", "flex├úo de pernas", "mesa flexora", "cadeira flexora", "flexora em p├®", "eleva├º├úo de panturrilha", "rosca b├¡ceps", "rosca scott", "rosca concentrada", "rosca martelo", "rosca de punho", "extens├úo de tr├¡ceps", "coice de tr├¡ceps", "tr├¡ceps na polia", "encolhimento de ombro", "remada alta", "eleva├º├úo lateral", "eleva├º├úo frontal", "desenvolvimento", "desenvolvimento militar", "desenvolvimento arnold", "crucifixo", "crossover", "peck deck", "pullover", "abdominal", "eleva├º├úo de pernas", "eleva├º├úo de joelhos", "prancha", "prancha lateral", "giro russo", "extens├úo lombar", "afundo", "passada no step", "alongamento", "mobilidade", "polichinelo", "burpee", "escalador", "pular corda"].includes(val)) {
        if (!exercise) {
          exercise = val;
          lower = lower.replace(key, "");
        }
      } else {
        if (!details.includes(val)) {
          details.push(val);
          lower = lower.replace(key, "");
        }
      }
    }
  }

  // Se sobrou alguma palavra n├úo traduzida (como nome de m├║sculo espec├¡fico ou detalhe raro), limpa caracteres especiais e anexa
  let remaining = lower.replace(/[^a-z0-9]/g, " ").replace(/\s+/g, " ").trim();
  if (remaining && remaining.length > 2) {
    // Dicion├írio r├ípido de termos remanescentes comuns
    const quickMap = {
      "calves": "para panturrilhas",
      "chest": "peitoral",
      "back": "costas",
      "hamstring": "posterior",
      "quadriceps": "quadr├¡pces",
      "glute": "gl├║teos",
      "neck": "pesco├ºo",
      "shoulder": "ombros",
      "triceps": "tr├¡ceps",
      "biceps": "b├¡ceps",
      "forearm": "antebra├ºo",
      "ankle": "tornozelo",
      "wrist": "punho",
      "finger": "dedos",
      "groin": "virilha",
      "hip": "quadril",
      "abductor": "abdutores",
      "adductor": "adutores",
      "toe": "dedos do p├®",
      "knee": "joelhos",
      "wheel": "roda",
      "hand": "m├úo"
    };
    for (const k of Object.keys(quickMap)) {
      if (remaining.includes(k)) {
        details.push(quickMap[k]);
        remaining = remaining.replace(k, "");
      }
    }
    remaining = remaining.trim();
    if (remaining && remaining.length > 2) {
      details.push(remaining);
    }
  }

  // Se n├úo identificou o exerc├¡cio principal, usa o nome original
  if (!exercise) {
    return name;
  }

  // Monta a frase em portugu├¬s seguindo a ordem natural de muscula├º├úo:
  // [Exerc├¡cio] + [Detalhe] + [Posi├º├úo] + [Equipamento]
  let finalName = exercise;
  if (details.length > 0) finalName += " " + details.join(" ");
  if (position) finalName += " " + position;
  if (equipment) finalName += " " + equipment;

  // Remove espa├ºos duplicados e limpa pontua├º├Áes
  finalName = finalName.replace(/\s+/g, ' ').replace(/\(\s*\)/g, '').trim();

  // Capitaliza a primeira letra
  return finalName.charAt(0).toUpperCase() + finalName.slice(1);
}

