const fs = require('fs');
const path = require('path');

// Adicione sua chave de API do Google Gemini Studio no .env como GEMINI_API_KEY
const API_KEY = process.env.GEMINI_API_KEY;

const rawDatasetPath = path.join(__dirname, '..', 'prisma', 'seeds', 'exercises_raw.json');
const outputPath = path.join(__dirname, '..', 'prisma', 'seeds', 'exercises_ptbr.json');

async function translateBatch(exercisesBatch) {
  const prompt = `
Voc├¬ ├® um especialista em educa├º├úo f├¡sica e fisiologia.
Traduza os seguintes exerc├¡cios do ingl├¬s para portugu├¬s do Brasil.
Voc├¬ deve retornar APENAS um array JSON v├ílido contendo os objetos atualizados.
N├úo adicione markdown (como \`\`\`json) na resposta, APENAS O ARRAY PURO.

Traduza os campos "name", "muscleGroup" (mapeado de "category" ou "target") e "equipment".
Mantenha os campos "gifUrl" e "videoUrl".

Aqui est├úo os exerc├¡cios:
${JSON.stringify(exercisesBatch, null, 2)}
  `;

  try {
    const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent?key=${API_KEY}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: {
            temperature: 0, // Ser determin├¡stico
        }
      })
    });

    const data = await response.json();
    if (data.error) {
      console.error("Erro na API:", data.error.message);
      return [];
    }

    let textResponse = data.candidates[0].content.parts[0].text;

    // Limpar block de markdown se a IA colocar sem querer
    textResponse = textResponse.replace(/```json/g, '').replace(/```/g, '').trim();

    return JSON.parse(textResponse);
  } catch (error) {
    console.error('Erro ao traduzir lote:', error);
    return [];
  }
}

async function main() {
  if (API_KEY === 'SUA_API_KEY_AQUI') {
    console.error("ÔÜá´©Å ERRO: Configure sua GEMINI_API_KEY no script ou no ambiente antes de rodar.");
    process.exit(1);
  }

  console.log("Lendo dataset raw...");
  const rawData = JSON.parse(fs.readFileSync(rawDatasetPath, 'utf8'));

  // Mapear para o formato do nosso schema Prisma antes de enviar
  const mappedData = rawData.map(ex => ({
    name: ex.name,
    muscleGroup: ex.category || ex.body_part || 'Geral',
    equipment: ex.equipment,
    description: ex.instructions?.en || null,
    gifUrl: ex.gif_url || null,
    videoUrl: null
  }));

  const BATCH_SIZE = 150;
  let translatedExercises = [];

  console.log(`Total de exerc├¡cios para traduzir: ${mappedData.length}`);

  for (let i = 0; i < mappedData.length; i += BATCH_SIZE) {
    console.log(`Processando lote ${Math.floor(i / BATCH_SIZE) + 1} de ${Math.ceil(mappedData.length / BATCH_SIZE)}...`);
    const batch = mappedData.slice(i, i + BATCH_SIZE);

    // Simplificar a descri├º├úo no envio para economizar tokens, ou remover se n├úo for usar a IA para traduzir descri├º├úo longa
    // Para baratear e n├úo estourar tokens, vamos traduzir s├│ o essencial e deixar description null ou simplificada
    let retries = 0;
    let sucesso = false;

    while (!sucesso && retries < 5) {
      console.log(`[${Math.round((i / mappedData.length) * 100)}%] Processando lote ${Math.floor(i / BATCH_SIZE) + 1} de ${Math.ceil(mappedData.length / BATCH_SIZE)}... (Tentativa ${retries + 1}/5)`);
      const batchToTranslate = batch.map(b => ({
        name: b.name,
        muscleGroup: b.muscleGroup,
        equipment: b.equipment,
        gifUrl: b.gifUrl
      }));

      const result = await translateBatch(batchToTranslate);

      if (result.length > 0) {
        translatedExercises = translatedExercises.concat(result);
        fs.writeFileSync(outputPath, JSON.stringify(translatedExercises, null, 2));
        sucesso = true;
      } else {
        retries++;
        console.log(`ÔÜá´©Å Limite atingido ou erro. Aguardando 30 segundos antes de tentar o mesmo lote de novo...`);
        await new Promise(r => setTimeout(r, 30000)); // Espera 30s se der erro
      }
    }

    if (!sucesso) {
      console.log("ÔØî Falha cr├¡tica no lote ap├│s 5 tentativas. Encerrando para n├úo corromper os dados.");
      break;
    }

    // Delay normal entre requisi├º├Áes com sucesso para n├úo estourar o limite (15 segundos)
    console.log("Lote traduzido! Aguardando 15s (Anti-Bloqueio Google)...");
    await new Promise(r => setTimeout(r, 15000));
  }

  if (translatedExercises.length === mappedData.length) {
    console.log(`\nÔ£à Tradu├º├úo 100% conclu├¡da! Arquivo salvo em ${outputPath}`);
    console.log(`Agora voc├¬ pode rodar 'npm run prisma:seed' (ou o script correspondente) para importar.`);
  } else {
    console.log(`\nÔÜá´©Å Tradu├º├úo parou pela metade. Progresso salvo em ${outputPath}`);
  }
}

main();

import { NextResponse } from "next/server";
import prisma from "@/lib/prisma";
import bcrypt from "bcryptjs";
import { z } from "zod";

// Lista de dom├¡nios tempor├írios/descart├íveis bloqueados
const DISPOSABLE_DOMAINS = [
  "mailinator.com",
  "tempmail.com",
  "10minutemail.com",
  "guerrillamail.com",
  "trashmail.com",
  "yopmail.com",
];

const registerSchema = z.object({
  name: z.string().min(2, "O nome deve ter pelo menos 2 caracteres"),
  email: z
    .string()
    .email("Endere├ºo de email inv├ílido")
    .transform((val) => val.trim().toLowerCase())
    .refine(
      (val) => {
        const domain = val.split("@")[1];
        return !DISPOSABLE_DOMAINS.includes(domain);
      },
      { message: "Por favor, utilize um provedor de e-mail v├ílido e permanente." }
    ),
  password: z.string().min(6, "A senha deve ter pelo menos 6 caracteres"),
  role: z.enum(["TRAINER", "STUDENT"]),
});


export async function POST(request: Request) {
  try {
    const body = await request.json();

    // Valida├º├úo com Zod
    const validation = registerSchema.safeParse(body);
    if (!validation.success) {
      return NextResponse.json(
        { errors: validation.error.flatten().fieldErrors },
        { status: 400 }
      );
    }

    const { name, email, password, role } = validation.data;

    // Verificar se email j├í existe
    const existingUser = await prisma.user.findUnique({
      where: { email },
    });

    if (existingUser) {
      return NextResponse.json(
        { error: "Este email j├í est├í cadastrado no sistema." },
        { status: 400 }
      );
    }

    // Hash da senha
    const hashedPassword = await bcrypt.hash(password, 10);

    // Transa├º├úo no Prisma para garantir cria├º├úo at├┤mica do usu├írio e seu perfil
    const newUser = await prisma.$transaction(async (tx) => {
      const user = await tx.user.create({
        data: {
          name,
          email,
          password: hashedPassword,
          role,
        },
      });

      if (role === "TRAINER") {
        await tx.trainerProfile.create({
          data: {
            userId: user.id,
          },
        });
      } else if (role === "STUDENT") {
        await tx.studentProfile.create({
          data: {
            userId: user.id,
          },
        });

        // Notificar todos os treinadores sobre o novo aluno dispon├¡vel
        const trainers = await tx.user.findMany({
          where: { role: "TRAINER" },
          select: { id: true }
        });

        if (trainers.length > 0) {
          await tx.notification.createMany({
            data: trainers.map((t) => ({
              userId: t.id,
              title: "Novo Aluno Registrado ­ƒåò",
              message: `${name} acabou de se cadastrar no sistema e est├í dispon├¡vel para ser vinculado!`,
            }))
          });
        }
      }

      return user;
    });

    return NextResponse.json(
      {
        message: "Usu├írio registrado com sucesso!",
        user: {
          id: newUser.id,
          name: newUser.name,
          email: newUser.email,
          role: newUser.role,
        },
      },
      { status: 201 }
    );
  } catch (error: any) {
    console.error("ERRO NO REGISTRO DE USU├üRIO:", error);
    return NextResponse.json(
      { error: "Ocorreu um erro interno ao processar seu cadastro." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/lib/auth";
import prisma from "@/lib/prisma";
import { z } from "zod";

const exerciseUpdateSchema = z.object({
  name: z.string().min(2, "O nome do exerc├¡cio deve ter pelo menos 2 caracteres").optional(),
  muscleGroup: z.string().min(2, "Selecione o grupo muscular prim├írio").optional(),
  equipment: z.string().min(2, "Selecione o equipamento utilizado").optional(),
  description: z.string().optional(),
  videoUrl: z.string().url("V├¡deo demonstrativo deve ser uma URL v├ílida").or(z.literal("")).optional(),
  gifUrl: z.string().url("GIF de movimento deve ser uma URL v├ílida").or(z.literal("")).optional(),
  alternatives: z.array(z.string()).optional(),
});

// PUT: Atualizar dados de um exerc├¡cio espec├¡fico
// TRAINER/ADMIN: podem editar todos os campos
// STUDENT: pode editar apenas o nome (renomear)
export async function PUT(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);

    if (!session) {
      return NextResponse.json(
        { error: "N├úo autorizado." },
        { status: 401 }
      );
    }

    const isTrainerOrAdmin = session.user.role === "TRAINER" || session.user.role === "ADMIN";
    const isStudent = session.user.role === "STUDENT";

    if (!isTrainerOrAdmin && !isStudent) {
      return NextResponse.json(
        { error: "N├úo autorizado." },
        { status: 401 }
      );
    }

    const { id } = await params;
    const body = await request.json();

    // Se for aluno, permitir apenas renomear
    if (isStudent) {
      const renameSchema = z.object({
        name: z.string().min(2, "O nome deve ter pelo menos 2 caracteres"),
      });
      const renameValidation = renameSchema.safeParse(body);
      if (!renameValidation.success) {
        return NextResponse.json(
          { errors: renameValidation.error.flatten().fieldErrors },
          { status: 400 }
        );
      }

      const existingExercise = await prisma.exercise.findUnique({ where: { id } });
      if (!existingExercise) {
        return NextResponse.json({ error: "Exerc├¡cio n├úo encontrado." }, { status: 404 });
      }

      if (renameValidation.data.name !== existingExercise.name) {
        const nameConflict = await prisma.exercise.findUnique({
          where: { name: renameValidation.data.name },
        });
        if (nameConflict) {
          return NextResponse.json(
            { error: "J├í existe outro exerc├¡cio com este nome." },
            { status: 400 }
          );
        }
      }

      const updated = await prisma.exercise.update({
        where: { id },
        data: { name: renameValidation.data.name },
      });
      return NextResponse.json(updated);
    }

    // Fluxo completo para TRAINER/ADMIN
    const validation = exerciseUpdateSchema.safeParse(body);

    if (!validation.success) {
      return NextResponse.json(
        { errors: validation.error.flatten().fieldErrors },
        { status: 400 }
      );
    }

    const existingExercise = await prisma.exercise.findUnique({
      where: { id },
    });

    if (!existingExercise) {
      return NextResponse.json(
        { error: "Exerc├¡cio n├úo encontrado." },
        { status: 404 }
      );
    }

    if (validation.data.name && validation.data.name !== existingExercise.name) {
      const nameConflict = await prisma.exercise.findUnique({
        where: { name: validation.data.name },
      });
      if (nameConflict) {
        return NextResponse.json(
          { error: "J├í existe outro exerc├¡cio cadastrado com este nome." },
          { status: 400 }
        );
      }
    }

    const updateData: any = { ...validation.data };
    if (validation.data.alternatives) {
      updateData.alternatives = JSON.stringify(validation.data.alternatives);
    }

    const updatedExercise = await prisma.exercise.update({
      where: { id },
      data: updateData,
    });

    return NextResponse.json(updatedExercise);
  } catch (error) {
    console.error("ERRO AO ATUALIZAR EXERC├ìCIO:", error);
    return NextResponse.json(
      { error: "Ocorreu um erro interno ao atualizar o exerc├¡cio." },
      { status: 500 }
    );
  }
}

// DELETE: Remover um exerc├¡cio espec├¡fico
export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);

    if (!session || (session.user.role !== "TRAINER" && session.user.role !== "ADMIN")) {
      return NextResponse.json(
        { error: "N├úo autorizado." },
        { status: 401 }
      );
    }

    const { id } = await params;

    // Verificar se o exerc├¡cio existe
    const existingExercise = await prisma.exercise.findUnique({
      where: { id },
    });

    if (!existingExercise) {
      return NextResponse.json(
        { error: "Exerc├¡cio n├úo encontrado." },
        { status: 404 }
      );
    }

    await prisma.exercise.delete({
      where: { id },
    });

    return NextResponse.json({ message: "Exerc├¡cio exclu├¡do com sucesso!" });
  } catch (error) {
    console.error("ERRO AO DELETAR EXERC├ìCIO:", error);
    return NextResponse.json(
      { error: "Ocorreu um erro interno ao excluir o exerc├¡cio. Certifique-se de que ele n├úo est├í associado a nenhuma ficha de treino." },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/lib/auth";
import prisma from "@/lib/prisma";
import { z } from "zod";

const partnerComparisonSchema = z.object({
  partnerId: z.string().min(1, "ID do parceiro de treino ├® obrigat├│rio"),
});

// GET: Retornar outros alunos vinculados ao mesmo treinador para sele├º├úo
export async function GET(request: Request) {
  try {
    const session = await getServerSession(authOptions);

    if (!session || session.user.role !== "STUDENT") {
      return NextResponse.json(
        { error: "N├úo autorizado." },
        { status: 401 }
      );
    }

    // Buscar perfil do aluno logado
    const student = await prisma.studentProfile.findUnique({
      where: { userId: session.user.id },
      select: { id: true, trainerId: true },
    });

    if (!student || !student.trainerId) {
      return NextResponse.json(
        { error: "Voc├¬ ainda n├úo possui um treinador vinculado." },
        { status: 400 }
      );
    }

    // Buscar outros alunos do mesmo treinador
    const partners = await prisma.studentProfile.findMany({
      where: {
        trainerId: student.trainerId,
        id: { not: student.id }, // Excluir o pr├│prio aluno
      },
      include: {
        user: {
          select: {
            id: true,
            name: true,
            email: true,
          },
        },
      },
    });

    return NextResponse.json(
      partners.map((p) => ({
        id: p.id,
        name: p.user.name,
        email: p.user.email,
      }))
    );
  } catch (error) {
    console.error("ERRO AO BUSCAR PARCEIROS:", error);
    return NextResponse.json(
      { error: "Erro interno no servidor." },
      { status: 500 }
    );
  }
}

// POST: Retornar a compara├º├úo detalhada de m├®tricas entre o aluno logado e o parceiro selecionado
export async function POST(request: Request) {
  try {
    const session = await getServerSession(authOptions);

    if (!session || session.user.role !== "STUDENT") {
      return NextResponse.json(
        { error: "N├úo autorizado." },
        { status: 401 }
      );
    }

    const body = await request.json();
    const validation = partnerComparisonSchema.safeParse(body);

    if (!validation.success) {
      return NextResponse.json(
        { errors: validation.error.flatten().fieldErrors },
        { status: 400 }
      );
    }

    const { partnerId } = validation.data;

    // 1. Aluno logado
    const student = await prisma.studentProfile.findUnique({
      where: { userId: session.user.id },
      include: { user: { select: { name: true } } },
    });

    if (!student) {
      return NextResponse.json({ error: "Aluno n├úo encontrado." }, { status: 404 });
    }

    // 2. Parceiro selecionado
    const partner = await prisma.studentProfile.findUnique({
      where: { id: partnerId },
      include: { user: { select: { name: true } } },
    });

    if (!partner) {
      return NextResponse.json({ error: "Parceiro de treino n├úo encontrado." }, { status: 404 });
    }

    // IDOR FIX: Verificar que o parceiro ├® do mesmo treinador
    if (!student.trainerId || student.trainerId !== partner.trainerId) {
      return NextResponse.json(
        { error: "Acesso negado. Voc├¬ s├│ pode comparar com parceiros do mesmo treinador." },
        { status: 403 }
      );
    }

    // 3. Coletar estat├¡sticas do aluno logado
    const studentSessions = await prisma.workoutSession.findMany({
      where: { studentId: student.id },
      include: { logs: true },
    });

    const studentTotalSessions = studentSessions.length;
    const studentTotalSets = studentSessions.reduce(
      (sum, s) => sum + s.logs.length,
      0
    );

    // 4. Coletar estat├¡sticas do parceiro
    const partnerSessions = await prisma.workoutSession.findMany({
      where: { studentId: partner.id },
      include: { logs: true },
    });

    const partnerTotalSessions = partnerSessions.length;
    const partnerTotalSets = partnerSessions.reduce(
      (sum, s) => sum + s.logs.length,
      0
    );

    // 5. Buscar exerc├¡cios em comum nos planos de treino dos dois alunos
    const studentPlanExercises = await prisma.workoutPlanExercise.findMany({
      where: { workoutPlan: { studentId: student.id } },
      include: {
        exercise: { select: { id: true, name: true, muscleGroup: true, equipment: true } },
      },
    });

    const partnerPlanExercises = await prisma.workoutPlanExercise.findMany({
      where: { workoutPlan: { studentId: partner.id } },
      include: {
        exercise: { select: { id: true, name: true, muscleGroup: true, equipment: true } },
      },
    });

    // IDs ├║nicos de exerc├¡cios de cada aluno
    const studentExerciseIds = new Set(studentPlanExercises.map((e) => e.exerciseId));
    const partnerExerciseIds = new Set(partnerPlanExercises.map((e) => e.exerciseId));

    // Exerc├¡cios em comum (interse├º├úo)
    const sharedExerciseIds = [...studentExerciseIds].filter((id) => partnerExerciseIds.has(id));

    // Montar lista de exerc├¡cios compartilhados com infos
    const exerciseMap = new Map<string, { name: string; muscleGroup: string; equipment: string }>();
    for (const pe of [...studentPlanExercises, ...partnerPlanExercises]) {
      if (sharedExerciseIds.includes(pe.exerciseId) && !exerciseMap.has(pe.exerciseId)) {
        exerciseMap.set(pe.exerciseId, {
          name: pe.exercise.name,
          muscleGroup: pe.exercise.muscleGroup,
          equipment: pe.exercise.equipment,
        });
      }
    }

    const sharedExercises = sharedExerciseIds.map((id) => ({
      exerciseId: id,
      ...exerciseMap.get(id)!,
    }));

    // 6. Comparar PRs (carga m├íxima) nos exerc├¡cios em comum
    const studentLogs = sharedExerciseIds.length > 0
      ? await prisma.exerciseLog.findMany({
          where: {
            studentId: student.id,
            exerciseId: { in: sharedExerciseIds },
          },
          include: { exercise: { select: { name: true } } },
        })
      : [];

    const partnerLogs = sharedExerciseIds.length > 0
      ? await prisma.exerciseLog.findMany({
          where: {
            studentId: partner.id,
            exerciseId: { in: sharedExerciseIds },
          },
          include: { exercise: { select: { name: true } } },
        })
      : [];

    // Fun├º├úo auxiliar para encontrar a carga m├íxima
    const getMaxWeight = (logsList: typeof studentLogs, exId: string) => {
      const filtered = logsList.filter((l) => l.exerciseId === exId);
      if (filtered.length === 0) return 0;
      return Math.max(...filtered.map((l) => l.weightUsed));
    };

    const exerciseComparison = sharedExerciseIds.map((id) => ({
      exerciseId: id,
      exerciseName: exerciseMap.get(id)?.name || "Exerc├¡cio",
      muscleGroup: exerciseMap.get(id)?.muscleGroup || "",
      myMax: getMaxWeight(studentLogs, id),
      partnerMax: getMaxWeight(partnerLogs, id),
    }));

    return NextResponse.json({
      myInfo: {
        name: student.user.name,
        sessionsCount: studentTotalSessions,
        setsCount: studentTotalSets,
      },
      partnerInfo: {
        name: partner.user.name,
        sessionsCount: partnerTotalSessions,
        setsCount: partnerTotalSets,
      },
      sharedExercises,
      exerciseComparison,
    });
  } catch (error) {
    console.error("ERRO AO GERAR COMPARA├ç├âO:", error);
    return NextResponse.json(
      { error: "Erro interno no servidor." },
      { status: 500 }
    );
  }
}

