                                      }`}
                                      style={{ width: `${percent}%` }}
                                    />
                                  </div>
                                  <p className={`text-[10px] ${achievement.unlocked ? "text-emerald-600 font-medium" : "text-zinc-400 font-normal italic"} mt-1.5`}>
                                    {hintText}
                                  </p>
                                </div>
                              </div>
                            );
                          })}
                      </div>
                    )}
                </div>
              </>
            )}
          </div>

    </>
  );
}

