source:
"use client";
import BrandLogo from "@/components/BrandLogo";
import WorkoutTab from "./components/WorkoutTab";
import PartnerTab from "./components/PartnerTab";
import WeightTab from "./components/WeightTab";
import AchievementsTab from "./components/AchievementsTab";
import WeatherCard from "./components/WeatherCard";

import { getAchievementStatusHint } from "@/lib/gamification";

import React, { useState, useEffect, useRef } from "react";
import { signOut, useSession } from "next-auth/react";
import Link from "next/link";
import {
  Dumbbell,
  LogOut,
  Loader2,
  Calendar,
  Activity,
  Play,
  Award,
  Sparkles,
  Users,
  TrendingUp,
  User,
  ArrowRight,
  RefreshCw,
  Edit,
  X,
  Bell,
  ChevronRight,
  Eye,
  Tv,
  Flame,
  Trophy,
  Shield,
  Scale,
  Zap,
  Swords,
  Lock,
  Crown,
} from "lucide-react";

interface Achievement {
  id: string;
  title: string;
  description: string;
  icon: string;
  xpReward: number;
  unlocked: boolean;
  progress: number;
  target: number;
  tier: number;
}

interface GamificationData {
  level: number;
  levelTitle: string;
  totalXp: number;
  currentLevelXp: number;
  nextLevelXpNeeded: number;
  streak: number;
  totalSessions: number;
  prsCount: number;
  measurementsCount: number;
  achievements: Achievement[];
}



interface Exercise {
  id: string;
  name: string;
  muscleGroup: string;
  equipment: string;
  sets: number;
  reps: string;
  restSeconds: number;
  method: string;
  videoUrl?: string | null;
  gifUrl?: string | null;
  description?: string | null;
}

interface WorkoutPlan {
  id: string;
  name: string;
  description: string | null;
  division: string;
  weekDays: string | null;
  exercises: Exercise[];
}

interface TrainerInfo {
  name: string;
  email: string;
}

interface Partner {
  id: string;
  name: string;
  email: string;
}

interface ComparisonData {
  myInfo: {
    name: string;
    sessionsCount: number;
    setsCount: number;
  };
  partnerInfo: {
    name: string;
    sessionsCount: number;
    setsCount: number;
  };
  sharedExercises: {
    exerciseId: string;
    name: string;
    muscleGroup: string;
    equipment: string;
  }[];
  exerciseComparison: {
    exerciseId: string;
    exerciseName: string;
    muscleGroup: string;
    myMax: number;
    partnerMax: number;
  }[];
}

const DAY_ORDER: Record<string, number> = {
  "Seg": 1,
  "Ter": 2,
  "Qua": 3,
  "Qui": 4,
  "Sex": 5,
  "S├íb": 6,
  "Dom": 7
};

function sortPlansByWeekDays(plansList: WorkoutPlan[]) {
  return [...plansList].sort((a, b) => {
    if (!a.weekDays && !b.weekDays) return 0;
    if (!a.weekDays) return 1;
    if (!b.weekDays) return -1;

    const aDays = a.weekDays.split(",").map(d => d.trim()).map(d => DAY_ORDER[d] || 999).sort((x, y) => x - y);
    const bDays = b.weekDays.split(",").map(d => d.trim()).map(d => DAY_ORDER[d] || 999).sort((x, y) => x - y);

    for (let i = 0; i < Math.max(aDays.length, bDays.length); i++) {
      const aVal = aDays[i] !== undefined ? aDays[i] : 999;
      const bVal = bDays[i] !== undefined ? bDays[i] : 999;
      if (aVal !== bVal) {
        return aVal - bVal;
      }
    }
    return 0;
  });
}

export default function StudentDashboard() {
  const { data: session } = useSession();
  
  const [plans, setPlans] = useState<WorkoutPlan[]>([]);
  const [trainer, setTrainer] = useState<TrainerInfo | null>(null);
  const [loading, setLoading] = useState(true);

  // Estados da Aba e Duelo de Parceiros
  const [activeTab, setActiveTab] = useState<"fichas" | "conquistas" | "dupla" | "peso">("fichas");
  const [selectedPlanForPreview, setSelectedPlanForPreview] = useState<WorkoutPlan | null>(null);
  const [activeVideoUrl, setActiveVideoUrl] = useState<string | null>(null);
  const [selectedTier, setSelectedTier] = useState<number>(1);
  const [achievementFilter, setAchievementFilter] = useState<"all" | "unlocked" | "locked">("all");

  const getYouTubeEmbedUrl = (url: string | null) => {
    if (!url) return null;
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=|shorts\/)([^#\&\?]*).*/;
    const match = url.match(regExp);
    if (match && match[2].length === 11) {
      return `https://www.youtube.com/embed/${match[2]}?autoplay=1`;
    }
    return url;
  };

  const getMediaUrl = (url: string | null) => {
    if (!url) return "";
    if (url.startsWith("http://") || url.startsWith("https://") || url.startsWith("/")) {
      return url;
    }
    if (url.startsWith("videos/") || url.startsWith("images/")) {
      return `https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/${url}`;
    }
    return url;
  };


  const handleTabChange = (tab: "fichas" | "conquistas" | "dupla" | "peso") => {
    setActiveTab(tab);
    localStorage.setItem("student_active_tab", tab);
  };
  const [partners, setPartners] = useState<Partner[]>([]);
  const [selectedPartnerId, setSelectedPartnerId] = useState("");
  const [partnerSearchQuery, setPartnerSearchQuery] = useState("");

  // Estados de Peso corporal
  interface WeightMeasurement {
    id: string;
    weight: number;
    date: string;
    bodyFat?: number | null;
    chest?: number | null;
    waist?: number | null;
    armLeft?: number | null;
    armRight?: number | null;
    thighLeft?: number | null;
    thighRight?: number | null;
    calfLeft?: number | null;
    calfRight?: number | null;
    photos?: string[];
  }
  const [measurements, setMeasurements] = useState<WeightMeasurement[]>([]);
  const [measurementsLoading, setMeasurementsLoading] = useState(false);
  const [newWeight, setNewWeight] = useState("");
  const [newWeightDate, setNewWeightDate] = useState("");
  const [savingWeight, setSavingWeight] = useState(false);
  const [weightError, setWeightError] = useState("");
  const [expandedMeasurementId, setExpandedMeasurementId] = useState<string | null>(null);
  const [selectedPhotoForZoom, setSelectedPhotoForZoom] = useState<string>("");

  // Estados de Notifica├º├Áes
  const [notifications, setNotifications] = useState<any[]>([]);
  const [showNotifications, setShowNotifications] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);

  // Ref para fechar notifica├º├Áes ao clicar fora
  const notificationRef = useRef<HTMLDivElement>(null);
  const [comparison, setComparison] = useState<ComparisonData | null>(null);
  const [comparisonLoading, setComparisonLoading] = useState(false);

  // Estados para Recordes Pessoais (PRs)
  const [prs, setPrs] = useState<any[]>([]);
  const [prsLoading, setPrsLoading] = useState(true);

  // Estados de Gamifica├º├úo (RPG)
  interface Achievement {
    id: string;
    title: string;
    description: string;
    icon: string;
    xpReward: number;
    unlocked: boolean;
    progress: number;
    target: number;
    tier: number;
  }
  interface GamificationData {
    level: number;
    levelTitle: string;
    totalXp: number;
    currentLevelXp: number;
    nextLevelXpNeeded: number;
    streak: number;
    totalSessions: number;
    prsCount: number;
    measurementsCount: number;
    achievements: Achievement[];
  }
  const [gamification, setGamification] = useState<GamificationData | null>(null);
  const [gamificationLoading, setGamificationLoading] = useState(true);

  interface RankingUser {
    id: string;
    name: string;
    email: string;
    image: string | null;
    totalXp: number;
    level: number;
    levelTitle: string;
    totalSessions: number;
  }
  interface RankingData {
    top5: RankingUser[];
    userPosition: number;
    totalParticipants: number;
  }
  const [ranking, setRanking] = useState<RankingData | null>(null);
  const [rankingLoading, setRankingLoading] = useState(true);


  // Estados para edi├º├úo de Ficha (Divis├úo & Dias)
  const [editingPlan, setEditingPlan] = useState<WorkoutPlan | null>(null);
  const [editDivision, setEditDivision] = useState("");
  const [editWeekDays, setEditWeekDays] = useState<string[]>([]);
  const [savingEdit, setSavingEdit] = useState(false);
  const [editError, setEditError] = useState("");

  const handleOpenEdit = (plan: WorkoutPlan) => {
    setEditingPlan(plan);
    setEditDivision(plan.division);
    setEditWeekDays(plan.weekDays ? plan.weekDays.split(",") : []);
    setEditError("");
  };

  const handleToggleEditDay = (day: string) => {
    if (editWeekDays.includes(day)) {
      setEditWeekDays(editWeekDays.filter((d) => d !== day));
    } else {
      setEditWeekDays([...editWeekDays, day]);
    }
  };

  const handleSaveEdit = async () => {
    if (!editingPlan) return;
    if (!editDivision.trim()) {
      setEditError("A divis├úo n├úo pode ser vazia.");
      return;
    }
    
    setSavingEdit(true);
    setEditError("");
    try {
      const response = await fetch(`/api/student/workout-plans/${editingPlan.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          division: editDivision,
          weekDays: editWeekDays.length > 0 ? editWeekDays.join(",") : null,
        }),
      });

      if (response.ok) {
        const updated = await response.json();
        const updatedPlans = plans.map((p) => p.id === editingPlan.id ? { ...p, division: updated.division, weekDays: updated.weekDays } : p);
        setPlans(sortPlansByWeekDays(updatedPlans));
        setEditingPlan(null);
      } else {
        const data = await response.json();
        setEditError(data.error || "Erro ao salvar altera├º├Áes.");
      }
    } catch (err) {
      setEditError("Erro ao salvar altera├º├Áes.");
    } finally {
      setSavingEdit(false);
    }
  };

  useEffect(() => {
    const fetchPlans = async () => {
      try {
        const response = await fetch("/api/student/workout-plans", { cache: 'no-store' });
        if (response.ok) {
          const data = await response.json();
          setPlans(sortPlansByWeekDays(data.plans));
          setTrainer(data.trainer);
        }
      } catch (error) {
        console.error("Erro ao buscar treinos:", error);
      } finally {
        setLoading(false);
      }
    };

    const fetchPrs = async () => {
      try {
        const response = await fetch("/api/student/prs", { cache: 'no-store' });
        if (response.ok) {
          const data = await response.json();
          setPrs(data);
        }
      } catch (error) {
        console.error("Erro ao buscar PRs:", error);
      } finally {
        setPrsLoading(false);
      }
    };

    const fetchGamification = async () => {
      try {
        const response = await fetch("/api/student/gamification", { cache: 'no-store' });
        if (response.ok) {
          const data = await response.json();
          setGamification(data);
          
          // Auto-select the first tier that has locked achievements (where the user is currently progressing)
          const firstLockedTier = data.achievements.find((a: Achievement) => !a.unlocked)?.tier || 4;
          setSelectedTier(firstLockedTier);
        }
      } catch (error) {
        console.error("Erro ao buscar dados de gamifica├º├úo:", error);
      } finally {
        setGamificationLoading(false);
      }
    };

    const fetchRanking = async () => {
      try {
        const response = await fetch("/api/student/ranking", { cache: 'no-store' });
        if (response.ok) {
          const data = await response.json();
          setRanking(data);
        }
      } catch (error) {
        console.error("Erro ao buscar ranking:", error);
      } finally {
        setRankingLoading(false);
      }
    };

    fetchPlans();
    fetchPrs();
    fetchGamification();
    fetchRanking();
  }, []);

  useEffect(() => {
    const savedTab = localStorage.getItem("student_active_tab");
    if (savedTab && ["fichas", "conquistas", "dupla", "peso"].includes(savedTab)) {
      setActiveTab(savedTab as "fichas" | "conquistas" | "dupla" | "peso");
    }
  }, []);

  // Buscar lista de parceiros ao carregar a aba de dupla
  useEffect(() => {
    if (activeTab === "dupla" && partners.length === 0) {
      const fetchPartners = async () => {
        try {
          const response = await fetch("/api/student/partner-comparison");
          if (response.ok) {
            const data = await response.json();
            setPartners(data);
          }
        } catch (error) {
          console.error("Erro ao buscar parceiros:", error);
        }
      };
      fetchPartners();
    }
  }, [activeTab, partners]);

  // Carregar dados de compara├º├úo ao selecionar um parceiro
  const handleSelectPartner = async (partnerId: string) => {
    setSelectedPartnerId(partnerId);
    if (!partnerId) {
      setComparison(null);
      return;
    }

    setComparisonLoading(true);
    try {
      const response = await fetch("/api/student/partner-comparison", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ partnerId }),
