"use client";
import BrandLogo from "@/components/BrandLogo";

import React, { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import { signOut, useSession } from "next-auth/react";
import Link from "next/link";
import {
  Dumbbell,
  LogOut,
  Search,
  Plus,
  Loader2,
  Trash2,
  ChevronRight,
  ChevronLeft,
  Info,
  CheckCircle,
  Sparkles,
  ArrowUp,
  ArrowDown,
  Pencil,
  Check,
} from "lucide-react";

interface Exercise {
  id: string;
  name: string;
  muscleGroup: string;
  equipment: string;
  description: string | null;
}

interface WorkoutExerciseInput {
  exerciseId: string;
  name: string;
  muscleGroup: string;
  equipment: string;
  sets: number;
  reps: string;
  restSeconds: number;
  method: string;
  recommendedRpe: number | null;
  recommendedWeight: number | null;
  notes: string;
  customName?: string | null;
}

const METHODS = ["Normal", "Drop Set", "Bi-Set", "Rest Pause", "At├® a falha"];

export default function NewPlanPage() {
  const params = useParams();
  const router = useRouter();
  const { data: session } = useSession();
  
  const studentId = params.id as string;

  // Estados do Aluno
  const [studentName, setStudentName] = useState("");
  const [studentLoading, setStudentLoading] = useState(true);
  const [workoutPlans, setWorkoutPlans] = useState<any[]>([]);

  // Estados dos Exerc├¡cios da Biblioteca
  const [library, setLibrary] = useState<Exercise[]>([]);
  const [libraryLoading, setLibraryLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedMuscle, setSelectedMuscle] = useState("todos");

  // Estados do Formul├írio de Treino
  const [editingPlanId, setEditingPlanId] = useState<string | null>(null);
  const [workoutName, setWorkoutName] = useState("");
  const [description, setDescription] = useState("");
  const [division, setDivision] = useState("A");
  const [weekDays, setWeekDays] = useState<string[]>([]);
  const [selectedExercises, setSelectedExercises] = useState<WorkoutExerciseInput[]>([]);
  const [isPlanLinked, setIsPlanLinked] = useState(false);
  const [updateLinked, setUpdateLinked] = useState(false);

  const handleToggleDay = (day: string) => {
    if (weekDays.includes(day)) {
      setWeekDays(weekDays.filter((d) => d !== day));
    } else {
      setWeekDays([...weekDays, day]);
    }
  };

  // Estados de A├º├Áes
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);

  // Estados para Edi├º├úo Inline do Nome do Exerc├¡cio
  const [editingCustomNameIndex, setEditingCustomNameIndex] = useState<number | null>(null);
  const [tempCustomName, setTempCustomName] = useState("");

  // Estados para Anima├º├úo de Reordena├º├úo
  const [animatingIndex, setAnimatingIndex] = useState<number | null>(null);
  const [animatingDirection, setAnimatingDirection] = useState<"up" | "down" | null>(null);

  // Estados da IA
  const [showAiModal, setShowAiModal] = useState(false);
  const [aiGoal, setAiGoal] = useState("");
  const [aiNotes, setAiNotes] = useState("");
  const [generatingAi, setGeneratingAi] = useState(false);

  // Carregar dados do aluno
  const fetchStudentDetails = async () => {
    try {
      const response = await fetch(`/api/trainer/students/${studentId}`);
      if (!response.ok) {
        router.push("/trainer/dashboard");
        return;
      }
      const data = await response.json();
      setStudentName(data.name);
      setWorkoutPlans(data.workoutPlans || []);
    } catch (err) {
      console.error("Erro ao buscar dados do aluno:", err);
    } finally {
      setStudentLoading(false);
    }
  };

  useEffect(() => {
    if (studentId) {
      fetchStudentDetails();
    }
  }, [studentId, router]);

  // Carregar biblioteca de exerc├¡cios
  useEffect(() => {
    const fetchLibrary = async () => {
      try {
        const params = new URLSearchParams();
        if (searchQuery) params.append("search", searchQuery);
        if (selectedMuscle && selectedMuscle !== "todos") {
          params.append("muscle", selectedMuscle);
        }
        const response = await fetch(`/api/exercises?${params.toString()}`);
        if (response.ok) {
          const data = await response.json();
          setLibrary(data);
        }
      } catch (err) {
        console.error("Erro ao buscar exerc├¡cios:", err);
      } finally {
        setLibraryLoading(false);
      }
    };

    fetchLibrary();
  }, [searchQuery, selectedMuscle]);

  // Adicionar exerc├¡cio ├á ficha ativa
  const handleAddExercise = (exercise: Exercise) => {
    const newWorkoutExercise: WorkoutExerciseInput = {
      exerciseId: exercise.id,
      name: exercise.name,
      muscleGroup: exercise.muscleGroup,
      equipment: exercise.equipment,
      sets: 4,
      reps: "10",
      restSeconds: 60,
      method: "Normal",
      recommendedRpe: null,
      recommendedWeight: null,
      notes: "",
    };

    setSelectedExercises([...selectedExercises, newWorkoutExercise]);
  };

  // Remover exerc├¡cio da ficha ativa
  const handleRemoveExercise = (index: number) => {
    const updated = [...selectedExercises];
    updated.splice(index, 1);
    setSelectedExercises(updated);
  };

  const handleMoveExerciseUp = (index: number) => {
    if (index === 0 || animatingIndex !== null) return;
    setAnimatingIndex(index);
    setAnimatingDirection("up");
    setTimeout(() => {
      const updated = [...selectedExercises];
      const temp = updated[index];
      updated[index] = updated[index - 1];
      updated[index - 1] = temp;
      setSelectedExercises(updated);
      setAnimatingIndex(null);
      setAnimatingDirection(null);
    }, 300);
  };

  const handleMoveExerciseDown = (index: number) => {
    if (index === selectedExercises.length - 1 || animatingIndex !== null) return;
    setAnimatingIndex(index);
    setAnimatingDirection("down");
    setTimeout(() => {
      const updated = [...selectedExercises];
      const temp = updated[index];
      updated[index] = updated[index + 1];
      updated[index + 1] = temp;
      setSelectedExercises(updated);
      setAnimatingIndex(null);
      setAnimatingDirection(null);
    }, 300);
  };

  // Atualizar par├ómetro de um exerc├¡cio adicionado
  const handleUpdateExerciseParam = (
    index: number,
    key: keyof WorkoutExerciseInput,
    value: any
  ) => {
    const updated = [...selectedExercises];
    updated[index] = {
      ...updated[index],
      [key]: value,
    };
    setSelectedExercises(updated);
  };

  // Carregar um treino existente para edi├º├úo no construtor
  const handleEditPlan = (plan: any) => {
    setEditingPlanId(plan.id);
    setWorkoutName(plan.name);
    setDescription(plan.description || "");
    setDivision(plan.division);
    setWeekDays(plan.weekDays ? plan.weekDays.split(",") : []);
    
    const isLinked = plan.parentPlanId !== null || (plan._count?.linkedPlans && plan._count.linkedPlans > 0);
    setIsPlanLinked(!!isLinked);
    setUpdateLinked(false);

    // Mapear os exerc├¡cios do plano para o formato do formul├írio
    const mapped = plan.exercises.map((pe: any) => ({
      exerciseId: pe.exerciseId,
      name: pe.exercise?.name || "Exerc├¡cio Desconhecido",
      muscleGroup: pe.exercise?.muscleGroup || "Outros",
      equipment: pe.exercise?.equipment || "Nenhum",
      sets: pe.sets,
      reps: pe.reps,
      restSeconds: pe.restSeconds,
      method: pe.method,
      recommendedRpe: pe.recommendedRpe,
      recommendedWeight: pe.recommendedWeight,
      notes: pe.notes || "",
      customName: pe.customName || "",
    }));
    setSelectedExercises(mapped);
    setError("");
    setSuccess(false);
  };

  // Resetar o formul├írio para criar um novo treino
  const handleResetForm = () => {
    setEditingPlanId(null);
    setWorkoutName("");
    setDescription("");
    setDivision("A");
    setWeekDays([]);
    setSelectedExercises([]);
    setIsPlanLinked(false);
    setUpdateLinked(false);
    setError("");
    setSuccess(false);
  };

  // Excluir um treino existente
  const handleDeletePlan = async (planId: string) => {
    if (!confirm("Tem certeza que deseja excluir esta ficha de treino?")) return;
    setError("");
    try {
      const response = await fetch(`/api/trainer/students/${studentId}/workout-plans?planId=${planId}`, {
        method: "DELETE",
      });
      if (response.ok) {
        setWorkoutPlans((prev) => prev.filter((p) => p.id !== planId));
        if (editingPlanId === planId) {
          handleResetForm();
        }
      } else {
        const data = await response.json();
        setError(data.error || "Erro ao excluir o treino.");
      }
    } catch (err) {
      setError("Erro ao se conectar com o servidor.");
    }
  };

  // Enviar formul├írio
  const handleSavePlan = async (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedExercises.length === 0) {
      setError("Adicione pelo menos um exerc├¡cio ao treino.");
      return;
    }

    setLoading(true);
    setError("");
    setSuccess(false);

    try {
      const url = `/api/trainer/students/${studentId}/workout-plans`;
      const method = editingPlanId ? "PUT" : "POST";
      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          planId: editingPlanId,
          name: workoutName,
          description,
          division,
          weekDays: weekDays.length > 0 ? weekDays.join(",") : null,
          updateLinked,
          exercises: selectedExercises.map((ex) => ({
            exerciseId: ex.exerciseId,
            sets: Number(ex.sets),
            reps: ex.reps,
            restSeconds: Number(ex.restSeconds),
            method: ex.method,
            recommendedRpe: ex.recommendedRpe ? Number(ex.recommendedRpe) : null,
            recommendedWeight: ex.recommendedWeight ? Number(ex.recommendedWeight) : null,
            notes: ex.notes || null,
            customName: ex.customName || null,
          })),
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        setError(data.error || `Ocorreu um erro ao ${editingPlanId ? "atualizar" : "salvar"} o treino.`);
        return;
      }

      setSuccess(true);
      
      // Recarregar os treinos
      await fetchStudentDetails();

      setTimeout(() => {
        setSuccess(false);
        if (!editingPlanId) {
          // Se for cria├º├úo de um novo treino, limpa o formul├írio
          handleResetForm();
        }
      }, 1500);
    } catch (err) {
      setError("Erro de rede. Verifique sua conex├úo.");
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateAiWorkout = async () => {
    setGeneratingAi(true);
    setError("");
    try {
      const response = await fetch(`/api/trainer/students/${studentId}/ai-workout`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          goal: aiGoal,
          notes: aiNotes,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        setError(data.error || "Erro ao gerar treino por IA.");
        setGeneratingAi(false);
        setShowAiModal(false);
        return;
      }

      if (data.workoutPlan) {
        const { name, division, description, weekDays: days, exercises } = data.workoutPlan;
        setWorkoutName(name || "");
        setDivision(division || "A");
        setDescription(description || "");
        if (Array.isArray(days)) {
          setWeekDays(days);
        } else if (typeof days === "string") {
          setWeekDays(days.split(",").map((d: string) => d.trim()));
        }
        
        const mappedExercises = exercises.map((ex: any) => ({
          exerciseId: ex.exerciseId,
          name: ex.name,
          muscleGroup: ex.muscleGroup,
          equipment: ex.equipment,
          sets: Number(ex.sets) || 4,
          reps: String(ex.reps) || "10",
          restSeconds: Number(ex.restSeconds) || 60,
          method: ex.method || "Normal",
          recommendedRpe: ex.recommendedRpe ? Number(ex.recommendedRpe) : null,
          recommendedWeight: ex.recommendedWeight ? Number(ex.recommendedWeight) : null,
          notes: ex.notes || "",
        }));

        setSelectedExercises(mappedExercises);
      }
      
      setShowAiModal(false);
    } catch (err) {
      console.error(err);
      setError("Erro ao se conectar com o servidor.");
    } finally {
      setGeneratingAi(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col text-[#0F172A]">
      {/* Header */}
      <header className="border-b border-[#E2E8F0] bg-white/80 backdrop-blur-md sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <div className="flex items-center gap-6">
            <BrandLogo size={36} />

            <nav className="hidden md:flex items-center gap-1">
              <Link
                href="/trainer/dashboard"
                className="px-4 py-2 rounded-xl text-sm font-semibold text-[#475569] hover:text-zinc-950 transition-colors"
              >
                Alunos
              </Link>
              <Link
                href="/trainer/exercises"
                className="px-4 py-2 rounded-xl text-sm font-semibold text-[#475569] hover:text-zinc-950 transition-colors"
              >
                Exerc├¡cios
              </Link>
            </nav>
          </div>

          <div className="flex items-center gap-4">
            <div className="text-right hidden sm:block">
              <p className="text-sm font-semibold text-[#0F172A]">
                {session?.user?.name || "Professor"}
              </p>
              <p className="text-[10px] text-[#2563EB] font-bold uppercase tracking-wider">
                Personal Trainer
              </p>
            </div>
            <button
              onClick={() => signOut({ callbackUrl: "/" })}
              className="p-2.5 rounded-xl border border-[#E2E8F0] hover:border-red-500/30 hover:bg-red-550/5 text-[#475569] hover:text-red-600 transition-all cursor-pointer"
            >
              <LogOut className="w-5 h-5" />
            </button>
          </div>
        </div>
      </header>

      {/* Header Contexto */}
      <section className="bg-white/60 border-b border-[#E2E8F0] py-6">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex items-center gap-3">
          <Link
            href="/trainer/dashboard"
            className="p-2 rounded-lg border border-[#E2E8F0] bg-white hover:border-zinc-300 text-[#475569] hover:text-zinc-950 transition-all"
          >
            <ChevronLeft className="w-4 h-4" />
          </Link>
          <div>
            <h2 className="font-display text-xl font-bold text-[#0F172A]">
              {studentLoading ? "Carregando..." : `Prescrever Treino: ${studentName}`}
            </h2>
            <p className="text-xs text-[#94A3B8] mt-0.5">Monte uma ficha de exerc├¡cios personalizada.</p>
          </div>
        </div>
      </section>

      {studentLoading ? (
        <div className="flex-1 flex flex-col items-center justify-center text-[#94A3B8] py-20">
          <Loader2 className="w-8 h-8 animate-spin text-[#2563EB] mb-2" />
          <p className="text-sm">Carregando dados do aluno...</p>
        </div>
      ) : (
        <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8 flex flex-col lg:flex-row gap-8">
          
          {/* Coluna Esquerda: Biblioteca de Exerc├¡cios & Treinos Salvos */}
          <section className="w-full lg:w-5/12 flex flex-col gap-6">
            {/* Biblioteca de Exerc├¡cios */}
            <div className="bg-white border border-[#E2E8F0] rounded-2xl p-5 shadow-sm space-y-4">
              <h3 className="text-xs font-bold text-[#475569] uppercase tracking-widest">
                Biblioteca de Exerc├¡cios
              </h3>

              {/* Filtros */}
              <div className="flex flex-col sm:flex-row gap-2">
                <div className="relative flex-1">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
                  <input
                    type="text"
                    placeholder="Buscar..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full pl-9 pr-3 py-2 rounded-xl bg-white border border-[#E2E8F0] text-xs focus:border-[#2563EB] outline-none text-[#0F172A] transition-all placeholder-zinc-400"
                  />
                </div>
                <select
                  value={selectedMuscle}
                  onChange={(e) => setSelectedMuscle(e.target.value)}
                  className="px-3 py-2 rounded-xl bg-white border border-[#E2E8F0] text-xs text-[#94A3B8] outline-none focus:border-[#2563EB] transition-all"
                >
                  <option value="todos">Todos M├║sculos</option>
                  <option value="Peito">Peito</option>
                  <option value="Costas">Costas</option>
                  <option value="Pernas">Pernas</option>
                  <option value="Ombros">Ombros</option>
                  <option value="Bra├ºos">Bra├ºos</option>
                  <option value="Core">Core</option>
                  <option value="Cardio">Cardio</option>
                  <option value="Aquecimento e Mobilidade">Aquecimento e Mobilidade</option>
                  <option value="Outros">Outros</option>
                </select>
              </div>

              {/* Lista */}
              <div className="space-y-2.5 max-h-[380px] overflow-y-auto pr-1">
                {libraryLoading ? (
                  <div className="flex items-center justify-center py-10 text-[#94A3B8]">
                    <Loader2 className="w-6 h-6 animate-spin text-[#2563EB] mr-2" />
                    <span className="text-xs">Carregando biblioteca...</span>
                  </div>
                ) : library.length === 0 ? (
                  <p className="text-xs text-[#94A3B8] text-center py-10">Nenhum exerc├¡cio encontrado.</p>
                ) : (
                  library.map((exercise) => (
                    <div
                      key={exercise.id}
                      className="p-3 bg-zinc-50 border border-[#E2E8F0] rounded-xl flex items-center justify-between gap-4 hover:border-[#2563EB]/30 transition-all group"
                    >
                      <div className="min-w-0">
                        <p className="text-xs font-semibold text-[#0F172A] truncate group-hover:text-[#2563EB] transition-colors">
                          {exercise.name}
                        </p>
                        <p className="text-[10px] text-[#94A3B8] mt-0.5">
                          {exercise.muscleGroup} ÔÇó {exercise.equipment}
                        </p>
                      </div>
                      <button
                        type="button"
                        onClick={() => handleAddExercise(exercise)}
                        className="p-1.5 rounded-lg border border-[#E2E8F0] hover:border-[#2563EB] hover:bg-[#00C2FF]/10 hover:text-[#2563EB] text-[#94A3B8] transition-all cursor-pointer flex-shrink-0"
                        title="Adicionar ├á ficha"
                      >
                        <Plus className="w-4 h-4" />
                      </button>
                    </div>
                  ))
                )}
              </div>
            </div>

            {/* Treinos Salvos */}
            <div className="bg-white border border-[#E2E8F0] rounded-2xl p-5 shadow-sm space-y-4">
              <h3 className="text-xs font-bold text-[#475569] uppercase tracking-widest">
                Treinos Salvos do Aluno
              </h3>
              
              {workoutPlans.length === 0 ? (
                <p className="text-xs text-[#94A3B8] text-center py-6">
                  Nenhum treino salvo para este aluno.
                </p>
              ) : (
                <div className="space-y-3 max-h-[300px] overflow-y-auto pr-1">
                  {workoutPlans.map((plan) => (
                    <div
                      key={plan.id}
                      className={`p-3 border rounded-xl flex items-center justify-between gap-4 transition-all ${
                        editingPlanId === plan.id
                          ? "bg-[#2563EB]/5 border-[#2563EB] shadow-sm"
                          : "bg-zinc-50 border-[#E2E8F0] hover:border-zinc-300"
                      }`}
                    >
                      <div className="min-w-0 flex-1">
                        <div className="flex items-center gap-2">
                          <span className="font-bold text-xs text-[#0F172A] truncate">
                            {plan.name}
                          </span>
                        </div>
                        {plan.createdAt && (
                          <p className="text-[10px] text-[#64748B] mt-1">
                            Criado em {new Date(plan.createdAt).toLocaleDateString('pt-BR')}
                          </p>
                        )}
                        {plan.description && (
                          <p className="text-[10px] text-[#94A3B8] truncate mt-0.5">
                            {plan.description}
                          </p>
                        )}
                        <p className="text-[9px] text-[#94A3B8] mt-1 font-semibold">
                          {plan.exercises?.length || 0} exerc├¡cios ÔÇó {plan.weekDays || "Qualquer dia"}
                        </p>
                      </div>
                      <div className="flex gap-1 flex-shrink-0">
                        <button
                          type="button"
                          onClick={() => handleEditPlan(plan)}
                          className="px-2.5 py-1.5 rounded-lg border border-[#E2E8F0] hover:border-[#2563EB] hover:bg-white text-[#2563EB] text-[10px] font-bold transition-all cursor-pointer"
                        >
                          Editar
                        </button>
                        <button
                          type="button"
                          onClick={() => handleDeletePlan(plan.id)}
                          className="p-1.5 rounded-lg border border-[#E2E8F0] hover:border-red-500 hover:bg-red-50 text-red-500 transition-all cursor-pointer"
                          title="Excluir ficha"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </section>
          {/* Coluna Direita: Construtor da Ficha */}
          <section className="w-full lg:w-7/12">
            <form onSubmit={handleSavePlan} className="bg-white border border-[#E2E8F0] rounded-2xl p-6 shadow-sm space-y-6">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <h3 className="text-xs font-bold text-[#475569] uppercase tracking-widest">
                    {editingPlanId ? "Editar Treino" : "Estrutura do Treino"}
                  </h3>
                  {editingPlanId && (
                    <span className="px-2 py-0.5 rounded-lg bg-[#2563EB]/10 text-[#2563EB] text-[9px] font-bold uppercase tracking-wider">
                      Modo Edi├º├úo
                    </span>
                  )}
                </div>
                <div className="flex gap-2">
                  {editingPlanId && (
                    <button
                      type="button"
                      onClick={handleResetForm}
                      className="px-3 py-2 rounded-xl border border-[#E2E8F0] hover:border-red-500 hover:bg-red-50 text-[#475569] hover:text-red-650 text-[10px] font-bold transition-all cursor-pointer"
                    >
                      Cancelar Edi├º├úo
                    </button>
                  )}
                  <button
                    type="button"
                    onClick={() => setShowAiModal(true)}
                    className="inline-flex items-center gap-1.5 px-3 py-2 rounded-xl bg-gradient-to-r from-[#2563EB] to-[#7C3AED] hover:from-[#1E40AF] hover:to-[#6D28D9] text-white font-bold text-[10px] uppercase tracking-wider transition-all cursor-pointer shadow-md shadow-purple-500/10"
                    title="Gerar um treino completo utilizando intelig├¬ncia artificial"
                  >
                    <Sparkles className="w-3.5 h-3.5" />
                    Criar treino com IA
                  </button>
                </div>
              </div>

              {error && (
                <div className="p-3 rounded-lg bg-red-50 border border-red-200 text-red-750 text-xs text-center font-semibold">
                  {error}
                </div>
              )}

              {success && (
                <div className="p-3 rounded-lg bg-[#00C2FF]/10 border border-[#2563EB]/30 text-[#1E40AF] text-xs text-center font-semibold animate-pulse">
                  {editingPlanId ? "Treino atualizado com sucesso!" : "Ficha criada e vinculada com sucesso!"}
                </div>
              )}

              {/* Informa├º├Áes B├ísicas da Ficha */}
              <div className="space-y-1">
                <label className="text-[10px] font-semibold text-[#94A3B8] uppercase tracking-wider block">Nome do Treino / Ficha</label>
                <input
                  type="text"
                  required
                  placeholder="Ex: Treino A - Peito & Tr├¡ceps"
                  value={workoutName}
                  onChange={(e) => setWorkoutName(e.target.value)}
                  className="w-full px-3.5 py-2 rounded-xl bg-white border border-[#E2E8F0] focus:border-[#2563EB] outline-none text-xs text-[#0F172A] placeholder-zinc-400 transition-all"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-semibold text-[#94A3B8] uppercase tracking-wider block">Descri├º├úo / Foco do Treino (Opcional)</label>
                <input
                  type="text"
                  placeholder="Ex: Foco em hipertrofia de peitoral, ├¬nfase em por├º├úo superior."
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  className="w-full px-3.5 py-2 rounded-xl bg-white border border-[#E2E8F0] focus:border-[#2563EB] outline-none text-xs text-[#0F172A] placeholder-zinc-400 transition-all"
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-semibold text-[#94A3B8] uppercase tracking-wider block">Dias da Semana Recomendados</label>
                <div className="flex flex-wrap gap-2">
                  {["Seg", "Ter", "Qua", "Qui", "Sex", "S├íb", "Dom"].map((day) => {
                    const isSelected = weekDays.includes(day);
                    return (
                      <button
                        key={day}
                        type="button"
                        onClick={() => handleToggleDay(day)}
                        className={`px-3 py-2 rounded-xl text-xs font-bold transition-all cursor-pointer border ${
                          isSelected
                            ? "bg-[#2563EB] border-[#2563EB] text-white shadow-sm shadow-blue-500/10"
                            : "bg-white border-[#E2E8F0] text-[#475569] hover:border-zinc-300"
                        }`}
                      >
                        {day}
                      </button>
                    );
                  })}
                </div>
              </div>

              {/* Lista de Exerc├¡cios Selecionados */}
              <div className="space-y-4">
                <span className="text-[10px] font-semibold text-[#94A3B8] uppercase tracking-wider block">Exerc├¡cios Adicionados ({selectedExercises.length})</span>
                
                {selectedExercises.length === 0 ? (
                  <div className="p-8 border border-dashed border-[#E2E8F0] rounded-xl text-center text-[#94A3B8] bg-zinc-50">
                    <Info className="w-6 h-6 mx-auto text-[#475569] mb-2" />
                    <p className="text-xs">Nenhum exerc├¡cio adicionado ainda.</p>
                    <p className="text-[10px] mt-0.5 text-[#94A3B8]">Selecione exerc├¡cios na biblioteca ao lado.</p>
                  </div>
                ) : (
                  <div className="space-y-3 max-h-[500px] overflow-y-auto pr-1">
                    {selectedExercises.map((exercise, index) => {
                      const isCurrentlyMoving = animatingIndex === index;
                      const isSwapTarget = animatingIndex !== null && (
                        (animatingDirection === "up" && index === animatingIndex - 1) ||
                        (animatingDirection === "down" && index === animatingIndex + 1)
                      );
                      
                      const transformStyle = isCurrentlyMoving
                        ? (animatingDirection === "up" ? "translateY(calc(-100% - 12px))" : "translateY(calc(100% + 12px))")
                        : (isSwapTarget
                          ? (animatingDirection === "up" ? "translateY(calc(100% + 12px))" : "translateY(calc(-100% - 12px))")
                          : "none");

                      return (
                        <div
                          key={index}
                          style={{
                            transform: transformStyle,
                            transition: animatingIndex !== null ? "transform 300ms cubic-bezier(0.4, 0, 0.2, 1), box-shadow 300ms cubic-bezier(0.4, 0, 0.2, 1), border-color 300ms" : "none",
                            zIndex: isCurrentlyMoving || isSwapTarget ? 10 : "auto",
                            boxShadow: isCurrentlyMoving || isSwapTarget ? "0 10px 25px -5px rgba(0, 0, 0, 0.15), 0 8px 10px -6px rgba(0, 0, 0, 0.15)" : "none",
                          }}
                          className={`p-4 bg-zinc-50 border border-[#E2E8F0] rounded-xl space-y-3 relative group transition-colors duration-300 ${isCurrentlyMoving || isSwapTarget ? "bg-white border-[#2563EB]/40 ring-1 ring-[#2563EB]/10" : ""}`}
                        >
                        <div className="absolute right-4 top-4 flex items-center gap-1.5">
                          <button
                            type="button"
                            disabled={index === 0}
                            onClick={() => handleMoveExerciseUp(index)}
                            className="p-1.5 rounded-lg border border-[#E2E8F0] bg-white hover:border-zinc-300 hover:bg-zinc-50 text-[#94A3B8] hover:text-zinc-950 transition-all cursor-pointer disabled:opacity-30 disabled:pointer-events-none"
                            title="Mover para cima"
                          >
                            <ArrowUp className="w-3.5 h-3.5" />
                          </button>
                          <button
                            type="button"
                            disabled={index === selectedExercises.length - 1}
                            onClick={() => handleMoveExerciseDown(index)}
                            className="p-1.5 rounded-lg border border-[#E2E8F0] bg-white hover:border-zinc-300 hover:bg-zinc-50 text-[#94A3B8] hover:text-zinc-950 transition-all cursor-pointer disabled:opacity-30 disabled:pointer-events-none"
                            title="Mover para baixo"
                          >
                            <ArrowDown className="w-3.5 h-3.5" />
                          </button>
                          <button
                            type="button"
                            onClick={() => handleRemoveExercise(index)}
                            className="p-1.5 rounded-lg border border-[#E2E8F0] bg-white hover:border-red-400 hover:bg-red-50 text-[#94A3B8] hover:text-red-650 transition-all cursor-pointer"
                            title="Remover exerc├¡cio"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        </div>

                        <div className="pr-10">
                          {editingCustomNameIndex === index ? (
                            <div className="flex items-center gap-1.5 mt-1">
                              <input
                                type="text"
                                value={tempCustomName}
                                onChange={(e) => setTempCustomName(e.target.value)}
                                placeholder={exercise.name}
                                className="px-2 py-1 rounded border border-[#E2E8F0] outline-none text-xs text-[#0F172A] focus:border-[#2563EB] font-bold min-w-[200px]"
                                autoFocus
                                onKeyDown={(e) => {
                                  if (e.key === "Enter") {
                                    handleUpdateExerciseParam(index, "customName", tempCustomName.trim());
                                    setEditingCustomNameIndex(null);
                                  } else if (e.key === "Escape") {
                                    setEditingCustomNameIndex(null);
                                  }
                                }}
                              />
                              <button
                                type="button"
                                onClick={() => {
                                  handleUpdateExerciseParam(index, "customName", tempCustomName.trim());
                                  setEditingCustomNameIndex(null);
                                }}
                                className="p-1.5 rounded bg-emerald-50 hover:bg-emerald-100 text-emerald-600 transition-all cursor-pointer"
                                title="Salvar"
                              >
                                <Check className="w-3.5 h-3.5" />
                              </button>
                              <button
                                type="button"
                                onClick={() => setEditingCustomNameIndex(null)}
                                className="text-[10px] text-[#94A3B8] hover:text-[#0F172A] px-1 font-semibold cursor-pointer"
                              >
                                Cancelar
                              </button>
                            </div>
                          ) : (
                            <div className="flex items-center flex-wrap gap-1">
                              <p className="text-xs font-bold text-[#0F172A]">
                                {exercise.customName ? (
                                  <>
                                    <span className="text-emerald-600 font-extrabold">{exercise.customName}</span>
                                    <span className="text-[10px] text-[#94A3B8] font-normal ml-1.5 italic">({exercise.name})</span>
                                  </>
                                ) : (
                                  exercise.name
                                )}
                              </p>
                              <button
                                type="button"
                                onClick={() => {
                                  setEditingCustomNameIndex(index);
                                  setTempCustomName(exercise.customName || "");
                                }}
                                className="p-1 rounded hover:bg-zinc-100 text-[#94A3B8] hover:text-[#2563EB] transition-all cursor-pointer"
                                title="Renomear exerc├¡cio para este aluno"
                              >
                                <Pencil className="w-3 h-3" />
                              </button>
                            </div>
                          )}
                          <p className="text-[9px] text-[#94A3B8] mt-0.5 uppercase font-semibold">
                            {exercise.muscleGroup} ÔÇó {exercise.equipment}
                          </p>
                        </div>

                        {/* Par├ómetros do Exerc├¡cio */}
                        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                          <div className="space-y-1">
                            <label className="text-[8px] font-bold text-[#94A3B8] uppercase block">S├®ries</label>
                            <input
                              type="number"
                              value={exercise.sets}
                              onChange={(e) => handleUpdateExerciseParam(index, "sets", Number(e.target.value))}
                              className="w-full px-2.5 py-1.5 rounded-lg bg-white border border-[#E2E8F0] outline-none text-xs text-[#0F172A] font-mono font-bold focus:border-[#2563EB]"
                            />
                          </div>
                          <div className="space-y-1">
                            <label className="text-[8px] font-bold text-[#94A3B8] uppercase block">Reps</label>
                            <input
                              type="text"
                              value={exercise.reps}
                              onChange={(e) => handleUpdateExerciseParam(index, "reps", e.target.value)}
                              placeholder="Ex: 8-12, Falha"
                              className="w-full px-2.5 py-1.5 rounded-lg bg-white border border-[#E2E8F0] outline-none text-xs text-[#0F172A] font-mono font-bold focus:border-[#2563EB]"
                            />
                          </div>
                          <div className="space-y-1">
                            <label className="text-[8px] font-bold text-[#94A3B8] uppercase block">Descanso (s)</label>
                            <input
                              type="number"
                              value={exercise.restSeconds}
                              onChange={(e) => handleUpdateExerciseParam(index, "restSeconds", Number(e.target.value))}
                              className="w-full px-2.5 py-1.5 rounded-lg bg-white border border-[#E2E8F0] outline-none text-xs text-[#0F172A] font-mono font-bold focus:border-[#2563EB]"
                            />
                          </div>
                          <div className="space-y-1">
                            <label className="text-[8px] font-bold text-[#94A3B8] uppercase block">M├®todo</label>
                            <select
                              value={exercise.method}
                              onChange={(e) => handleUpdateExerciseParam(index, "method", e.target.value)}
                              className="w-full px-2.5 py-1.5 rounded-lg bg-white border border-[#E2E8F0] outline-none text-xs text-[#475569] focus:border-[#2563EB]"
                            >
                              {METHODS.map((m) => (
                                <option key={m} value={m}>
                                  {m}
                                </option>
                              ))}
                            </select>
                          </div>
                        </div>

                        {/* Par├ómetros Avan├ºados (Peso recomendado e notas) */}
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                          <div className="space-y-1">
                            <label className="text-[8px] font-bold text-[#94A3B8] uppercase block">Peso Sugerido (kg)</label>
                            <input
                              type="number"
                              step="any"
                              placeholder="Ex: 24"
                              value={exercise.recommendedWeight || ""}
                              onChange={(e) => handleUpdateExerciseParam(index, "recommendedWeight", e.target.value ? Number(e.target.value) : null)}
                              className="w-full px-2.5 py-1.5 rounded-lg bg-white border border-[#E2E8F0] outline-none text-xs text-[#0F172A] font-mono focus:border-[#2563EB]"
                            />
                          </div>
                          <div className="space-y-1">
                            <label className="text-[8px] font-bold text-[#94A3B8] uppercase block">Anota├º├úo R├ípida</label>
                            <input
                              type="text"
                              placeholder="Foco na cad├¬ncia..."
                              value={exercise.notes || ""}
                              onChange={(e) => handleUpdateExerciseParam(index, "notes", e.target.value)}
                              className="w-full px-2.5 py-1.5 rounded-lg bg-white border border-[#E2E8F0] outline-none text-xs text-[#0F172A] focus:border-[#2563EB]"
                            />
                          </div>
                        </div>
                      </div>
                      );
                    })}
                  </div>
                )}
              </div>

              {/* Op├º├úo Atualizar Treino Vinculado */}
              {editingPlanId && isPlanLinked && (
                <div className="flex items-center gap-2 p-3.5 bg-blue-50 border border-blue-100 rounded-xl">
                  <input
                    type="checkbox"
                    id="updateLinked"
                    checked={updateLinked}
                    onChange={(e) => setUpdateLinked(e.target.checked)}
                    className="w-4 h-4 text-[#2563EB] border-[#E2E8F0] rounded focus:ring-[#2563EB] cursor-pointer"
                  />
                  <label htmlFor="updateLinked" className="text-xs font-semibold text-[#1E40AF] cursor-pointer select-none">
                    Atualizar treino vinculado
                  </label>
                </div>
              )}

              {/* Bot├úo Salvar Treino */}
              <button
                type="submit"
                disabled={loading || success}
                className="w-full py-3.5 px-4 rounded-xl bg-[#2563EB] hover:bg-[#1E40AF] text-white font-bold text-xs transition-all flex items-center justify-center gap-2 cursor-pointer disabled:opacity-50 disabled:pointer-events-none"
              >
                {loading ? (
                  <Loader2 className="w-5 h-5 animate-spin" />
                ) : (
                  <>
                    {editingPlanId ? "Salvar Altera├º├Áes no Treino" : "Salvar e Atribuir Treino"}
                    <CheckCircle className="w-4 h-4" />
                  </>
                )}
              </button>
            </form>
          </section>

        </main>
      )}

      {/* Modal de Cria├º├úo de Treino com IA */}
      {showAiModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-white border border-[#E2E8F0] rounded-2xl w-full max-w-md p-6 shadow-xl space-y-4">
            <div className="flex items-center justify-between border-b border-[#E2E8F0] pb-3">
              <div className="flex items-center gap-2">
                <Sparkles className="w-5 h-5 text-[#2563EB]" />
                <h4 className="font-bold text-[#0F172A] text-sm">Criar Treino com Intelig├¬ncia Artificial</h4>
              </div>
              <button
                type="button"
                onClick={() => setShowAiModal(false)}
                className="text-[#94A3B8] hover:text-[#0F172A] text-xs font-semibold cursor-pointer"
              >
                Cancelar
              </button>
            </div>
            
            <div className="space-y-3">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-[#94A3B8] uppercase tracking-wider block">Objetivo do Treino</label>
                <input
                  type="text"
                  placeholder="Ex: Hipertrofia de Bra├ºos, Emagrecimento, etc."
                  value={aiGoal}
                  onChange={(e) => setAiGoal(e.target.value)}
                  className="w-full px-3.5 py-2 rounded-xl bg-[#F8FAFC] border border-[#E2E8F0] focus:border-[#2563EB] outline-none text-xs text-[#0F172A] transition-all"
                />
              </div>
              
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-[#94A3B8] uppercase tracking-wider block">Observa├º├Áes / Limita├º├Áes do Aluno</label>
                <textarea
                  placeholder="Ex: Aluno tem dor no joelho esquerdo, evitar agachamento livre. Foco em cad├¬ncia lenta."
                  value={aiNotes}
                  onChange={(e) => setAiNotes(e.target.value)}
                  rows={3}
                  className="w-full px-3.5 py-2 rounded-xl bg-[#F8FAFC] border border-[#E2E8F0] focus:border-[#2563EB] outline-none text-xs text-[#0F172A] transition-all resize-none"
                />
              </div>
            </div>

            <div className="pt-2">
              <button
                type="button"
                disabled={generatingAi}
                onClick={handleGenerateAiWorkout}
                className="w-full py-3 px-4 rounded-xl bg-gradient-to-r from-[#2563EB] to-[#7C3AED] hover:from-[#1E40AF] hover:to-[#6D28D9] text-white font-bold text-xs transition-all flex items-center justify-center gap-2 cursor-pointer disabled:opacity-50"
              >
                {generatingAi ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    Gerando Treino...
                  </>
                ) : (
                  <>
                    <Sparkles className="w-4 h-4" />
                    Gerar Ficha Completa
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";
import BrandLogo from "@/components/BrandLogo";

import React, { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import { signOut, useSession } from "next-auth/react";
import Link from "next/link";
import {
  Dumbbell,
  LogOut,
  Loader2,
  ChevronLeft,
  Activity,
  Award,
  Calendar,
  Sparkles,
  ArrowRight,
  Clock,
  Cpu,
  Info,
} from "lucide-react";

interface SessionLog {
  id: string;
  date: string;
  durationMinutes: number;
  satisfaction: number;
}

interface ExerciseHistoryPoint {
  date: string;
  maxWeight: number;
  repsAtMaxWeight: number;
}

interface ExerciseProgress {
  exerciseId: string;
  name: string;
  muscleGroup: string;
  history: ExerciseHistoryPoint[];
}

interface Suggestion {
  exerciseId: string;
  exerciseName: string;
  currentWeight: number;
  suggestedWeight: number;
  reason: string;
}

export default function StudentProgressPage() {
  const params = useParams();
  const router = useRouter();
  const { data: session } = useSession();
  
  const studentId = params.id as string;

  const [studentName, setStudentName] = useState("");
  const [studentEmail, setStudentEmail] = useState("");
  const [totalSessions, setTotalSessions] = useState(0);
  const [recentSessions, setRecentSessions] = useState<SessionLog[]>([]);
  const [progressData, setProgressData] = useState<ExerciseProgress[]>([]);
  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
  
  const [loading, setLoading] = useState(true);

  // Estados do Copilot IA
  const [copilotAnalysis, setCopilotAnalysis] = useState("");
  const [copilotLoading, setCopilotLoading] = useState(false);

  useEffect(() => {
    const fetchProgress = async () => {
      try {
        const response = await fetch(`/api/trainer/students/${studentId}/progress`);
        if (!response.ok) {
          router.push("/trainer/dashboard");
          return;
        }

        const data = await response.json();
        setStudentName(data.studentName);
        setStudentEmail(data.studentEmail);
        setTotalSessions(data.totalSessionsCount);
        setRecentSessions(data.recentSessions);
        setProgressData(data.exerciseProgress);
        setSuggestions(data.progressionSuggestions);
      } catch (err) {
        console.error("Erro ao buscar progresso:", err);
      } finally {
        setLoading(false);
      }
    };

    if (studentId) {
      fetchProgress();
    }
  }, [studentId, router]);

  // Fun├º├úo para chamar o Copilot IA
  const handleRequestCopilot = async () => {
    setCopilotLoading(true);
    setCopilotAnalysis("");
    try {
      const response = await fetch(`/api/trainer/students/${studentId}/copilot`, {
        method: "POST",
      });
      if (response.ok) {
        const data = await response.json();
        setCopilotAnalysis(data.analysis);
      }
    } catch (err) {
      console.error("Erro ao acionar o Copilot IA:", err);
    } finally {
      setCopilotLoading(false);
    }
  };

  // Mini Renderizador Nativo de Markdown Estilizado
  const renderMarkdown = (text: string) => {
    return text.split("\n").map((line, idx) => {
      if (line.startsWith("## ")) {
        return (
          <h3 key={idx} className="font-display font-extrabold text-sm text-[#0F172A] mt-5 mb-2.5 tracking-tight border-b border-[#E2E8F0] pb-1">
            {line.replace("## ", "")}
          </h3>
        );
      }
      if (line.startsWith("### ")) {
        return (
          <h4 key={idx} className="font-display font-bold text-xs text-[#2563EB] mt-4 mb-2">
            {line.replace("### ", "")}
          </h4>
        );
      }
      if (line.startsWith("> [!NOTE]")) {
        return null;
      }
      if (line.startsWith("> ")) {
        return (
          <div key={idx} className="p-3.5 rounded-xl bg-zinc-50 border border-[#2563EB]/20 text-[#475569] text-xs italic my-3 leading-relaxed">
            {line.replace("> ", "")}
          </div>
        );
      }
      if (line.startsWith("* ") || line.startsWith("- ")) {
        const cleanLine = line.replace(/^[\*\-]\s+/, "");
        return (
          <li key={idx} className="text-xs text-[#94A3B8] list-disc ml-5 mt-1">
            {cleanLine}
          </li>
        );
      }
      if (line.trim() === "") return <div key={idx} className="h-2" />;
      return (
        <p key={idx} className="text-xs text-[#94A3B8] leading-relaxed mt-1">
          {line}
        </p>
      );
    });
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col text-[#0F172A]">
      {/* Header */}
      <header className="border-b border-[#E2E8F0] bg-white/80 backdrop-blur-md sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <div className="flex items-center gap-6">
            <BrandLogo size={36} />

            <nav className="hidden md:flex items-center gap-1">
              <Link
                href="/trainer/dashboard"
                className="px-4 py-2 rounded-xl text-sm font-semibold text-[#475569] hover:text-zinc-950 transition-colors"
              >
                Alunos
              </Link>
              <Link
                href="/trainer/exercises"
                className="px-4 py-2 rounded-xl text-sm font-semibold text-[#475569] hover:text-zinc-950 transition-colors"
              >
                Exerc├¡cios
              </Link>
            </nav>
          </div>

          <div className="flex items-center gap-4">
            <div className="text-right hidden sm:block">
              <p className="text-sm font-semibold text-[#0F172A]">
                {session?.user?.name || "Professor"}
              </p>
              <p className="text-[10px] text-[#2563EB] font-bold uppercase tracking-wider">
                Personal Trainer
              </p>
            </div>
            <button
              onClick={() => signOut({ callbackUrl: "/" })}
              className="p-2.5 rounded-xl border border-[#E2E8F0] hover:border-red-500/30 hover:bg-red-550/5 text-[#475569] hover:text-red-600 transition-all cursor-pointer"
            >
              <LogOut className="w-5 h-5" />
            </button>
          </div>
        </div>
      </header>

      {/* Header Contexto */}
      <section className="bg-white/60 border-b border-[#E2E8F0] py-6">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div className="flex items-center gap-3">
            <Link
              href="/trainer/dashboard"
              className="p-2 rounded-lg border border-[#E2E8F0] bg-white hover:border-zinc-300 text-[#475569] hover:text-zinc-950 transition-all"
            >
              <ChevronLeft className="w-4 h-4" />
            </Link>
            <div>
              <h2 className="font-display text-xl font-bold text-[#0F172A]">
                {loading ? "Carregando evolu├º├úo..." : `Evolu├º├úo de Cargas: ${studentName}`}
              </h2>
              <p className="text-xs text-[#94A3B8] mt-0.5">{studentEmail}</p>
            </div>
          </div>

          {/* Bot├úo Copilot IA */}
          {!loading && (
            <button
              onClick={handleRequestCopilot}
              disabled={copilotLoading}
              className="px-4 py-2.5 rounded-xl bg-[#2563EB] hover:bg-[#1E40AF] text-white font-bold text-xs transition-all shadow-lg shadow-blue-500/10 flex items-center gap-2 cursor-pointer disabled:opacity-50 disabled:pointer-events-none"
            >
              {copilotLoading ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Analisando dados...
                </>
              ) : (
                <>
                  <Cpu className="w-4 h-4" />
                  An├ílise Copilot IA
                </>
              )}
            </button>
          )}
        </div>
      </section>

      {loading ? (
        <div className="flex-1 flex flex-col items-center justify-center text-[#94A3B8] py-20">
          <Loader2 className="w-8 h-8 animate-spin text-[#2563EB] mb-2" />
          <p className="text-sm">Buscando m├®tricas de evolu├º├úo...</p>
        </div>
      ) : (
        <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">
          
          {/* Sess├úo de exibi├º├úo do Copilot IA */}
          {(copilotLoading || copilotAnalysis) && (
            <section className="animate-slide-down">
              <div className="glass-card rounded-2xl p-6 border border-[#2563EB]/30 bg-white relative overflow-hidden shadow-sm">
                <div className="absolute top-0 right-0 w-32 h-32 bg-[#2563EB]/5 rounded-full blur-3xl pointer-events-none" />
                
                <div className="flex items-center gap-2 mb-4">
                  <div className="p-1.5 rounded-lg bg-[#00C2FF]/10 text-[#2563EB]">
                    <Cpu className="w-4 h-4" />
                  </div>
                  <h3 className="font-display font-bold text-sm text-[#0F172A] uppercase tracking-wider">
                    TechFitness Copilot IA ÔÇö Recomenda├º├úo de Periodiza├º├úo
                  </h3>
                </div>

                {copilotLoading ? (
                  <div className="flex flex-col items-center justify-center py-10 text-[#94A3B8]">
                    <Loader2 className="w-6 h-6 animate-spin text-[#2563EB] mb-2" />
                    <p className="text-xs">O Copilot est├í analisando as dobras f├¡sicas, cargas e presen├ºas do aluno...</p>
                  </div>
                ) : (
                  <div className="space-y-1.5 max-w-none">
                    {renderMarkdown(copilotAnalysis)}
                  </div>
                )}
              </div>
            </section>
          )}

          {/* Bloco 1: Sugest├Áes de Progress├úo Inteligente de Carga */}
          <section>
            <h3 className="text-xs font-bold text-[#475569] uppercase tracking-widest mb-4 flex items-center gap-2">
              <Sparkles className="w-4 h-4 text-[#2563EB] fill-[#2563EB]/10" /> Recomenda├º├Áes de Carga Inteligentes
            </h3>

            {suggestions.length === 0 ? (
              <div className="glass-card rounded-2xl p-6 text-[#94A3B8] border border-[#E2E8F0] bg-white shadow-sm flex items-center gap-3">
                <Info className="w-5 h-5 text-[#2563EB]" />
                <p className="text-xs">
                  Sem recomenda├º├Áes de progress├úo ativas no momento. O aluno precisa bater o topo de repeti├º├Áes prescrito em 2 treinos seguidos para o algoritmo sugerir um aumento.
                </p>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {suggestions.map((s) => (
                  <div
                    key={s.exerciseId}
                    className="glass-card rounded-2xl p-5 border border-[#E2E8F0] bg-white relative overflow-hidden shadow-sm hover:border-[#2563EB]/30 transition-all duration-300"
                  >
                    <div className="absolute top-0 right-0 w-20 h-20 bg-[#2563EB]/5 rounded-full blur-xl" />
                    
                    <h4 className="font-display font-semibold text-sm text-zinc-950 leading-tight mb-2">
                      {s.exerciseName}
                    </h4>

                    <div className="flex items-center gap-4 py-3 my-3 border-y border-[#E2E8F0]">
                      <div>
                        <span className="text-[9px] text-[#94A3B8] uppercase tracking-wider block font-semibold">Carga Anterior</span>
                        <span className="text-base font-mono font-bold text-[#94A3B8]">{s.currentWeight}kg</span>
                      </div>
                      <ArrowRight className="w-4 h-4 text-[#2563EB] stroke-[3px] mt-3" />
                      <div>
                        <span className="text-[9px] text-[#2563EB] uppercase tracking-wider block font-semibold">Nova Carga Sugerida</span>
                        <span className="text-base font-mono font-bold text-[#2563EB]">{s.suggestedWeight}kg</span>
                      </div>
                    </div>

                    <p className="text-[10px] text-[#94A3B8] leading-relaxed">
                      <strong>Motivo:</strong> {s.reason}
                    </p>
                  </div>
                ))}
              </div>
            )}
          </section>

          {/* Grid de Duas Colunas */}
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            
            {/* Coluna Direita / Frequ├¬ncia */}
            <section className="lg:col-span-4 space-y-6">
              <h3 className="text-xs font-bold text-[#475569] uppercase tracking-widest flex items-center gap-2">
                <Calendar className="w-4 h-4 text-[#2563EB]" /> Hist├│rico de Presen├ºa
              </h3>

              <div className="bg-white border border-[#E2E8F0] rounded-2xl p-5 shadow-sm space-y-4">
                <div className="flex justify-between items-center pb-3 border-b border-[#E2E8F0]">
                  <span className="text-xs font-semibold text-[#94A3B8]">Total de Treinos Feitos</span>
                  <span className="font-mono text-xs font-bold text-[#0F172A] bg-white px-2 py-0.5 rounded border border-[#E2E8F0]">
                    {totalSessions} treinos
                  </span>
                </div>

                <div className="space-y-3 max-h-[360px] overflow-y-auto pr-1">
                  {recentSessions.length === 0 ? (
                    <p className="text-xs text-[#94A3B8] text-center py-6">Nenhum treino conclu├¡do ainda.</p>
                  ) : (
                    recentSessions.map((session) => (
                      <div key={session.id} className="p-3 bg-zinc-50 rounded-xl flex items-center justify-between border border-[#E2E8F0] text-xs">
                        <div className="flex items-center gap-2">
                          <Clock className="w-3.5 h-3.5 text-[#94A3B8]" />
                          <span className="font-semibold text-[#0F172A]">
                            {new Date(session.date).toLocaleDateString("pt-BR")}
                          </span>
                        </div>
                        <div className="flex gap-2">
                          <span className="font-mono text-[10px] text-[#94A3B8] bg-zinc-200/50 px-1.5 py-0.5 rounded">
                            {session.durationMinutes} min
                          </span>
                          <span className="font-mono text-[10px] text-[#2563EB] bg-[#00C2FF]/10 px-1.5 py-0.5 rounded border border-cyan-900/50">
                            RPE {session.satisfaction}/10
                          </span>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </div>
            </section>

            {/* Coluna Esquerda / Hist├│rico de For├ºa por Exerc├¡cio */}
            <section className="lg:col-span-8 space-y-6">
              <h3 className="text-xs font-bold text-[#475569] uppercase tracking-widest flex items-center gap-2">
                <Activity className="w-4 h-4 text-[#2563EB]" /> Hist├│rico de Progress├úo de For├ºa
              </h3>

              <div className="bg-white border border-[#E2E8F0] rounded-2xl p-5 shadow-sm space-y-6">
                {progressData.length === 0 ? (
                  <p className="text-xs text-[#94A3B8] text-center py-12">Nenhum registro de progress├úo encontrado.</p>
                ) : (
                  <div className="space-y-6">
                    {progressData.map((exercise) => (
                      <div key={exercise.exerciseId} className="space-y-3 pb-6 border-b border-[#E2E8F0] last:border-b-0 last:pb-0">
                        <div className="flex justify-between items-center">
                          <div>
                            <h4 className="text-xs font-bold text-[#0F172A]">{exercise.name}</h4>
                            <span className="text-[9px] text-[#94A3B8] uppercase font-semibold">{exercise.muscleGroup}</span>
                          </div>
                          
                          {/* Recorde Hist├│rico */}
                          {exercise.history.length > 0 && (
                            <div className="flex items-center gap-1.5 text-xs text-amber-600 bg-amber-50 border border-amber-100 px-2 py-0.5 rounded-lg">
                              <Award className="w-3.5 h-3.5" />
                              <span className="font-bold font-mono">
                                PR: {Math.max(...exercise.history.map(h => h.maxWeight))}kg
                              </span>
                            </div>
                          )}
                        </div>

                        {/* Linha do Tempo de Peso */}
                        <div className="flex gap-2 overflow-x-auto py-2 pr-2">
                          {exercise.history.map((pt, ptIdx) => (
                            <div key={ptIdx} className="bg-zinc-50 border border-[#E2E8F0] rounded-xl p-3 flex flex-col min-w-24 text-center items-center justify-center flex-shrink-0">
                              <span className="text-[8px] text-[#94A3B8] font-semibold">{new Date(pt.date).toLocaleDateString("pt-BR", { day: "numeric", month: "short" })}</span>
                              <span className="text-sm font-mono font-bold text-[#0F172A] mt-1">{pt.maxWeight}kg</span>
                              <span className="text-[9px] text-[#94A3B8] font-medium font-mono mt-0.5">{pt.repsAtMaxWeight} reps</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </section>

          </div>
        </main>
      )}
    </div>
  );
}
